-- =============================================================================
-- 475 — LE CAHIER D'EXERCICES DE 5E (partie 4)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/5e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 475 --niveau 5e --fichiers francais.n1,francais.n2,histoire-geo.n1 --suffixe 4 > supabase/contenu/475_exercices_5e_4.sql
--
-- 72 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   francais.n1             21 exercices · 7 chapitres
--   francais.n2             18 exercices · 6 chapitres
--   histoire-geo.n1         33 exercices · 11 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('8f784bec-0277-5d05-b70e-7d47fb81e7bc'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le carnet d’un marin","competence":"analyser-texte","situation":"Après six semaines de mer, un jeune marin note chaque soir ce qu’il découvre. Sa classe a retrouvé des pages de ce carnet imaginaire : à toi de repérer ce qui fait d’un texte un récit de voyage.","documents":[{"id":"carnet","type":"texte","genre":"recit","titre":"Pages du carnet","blocs":["Lundi 14 mars. Après six semaines de mer, j’aperçois enfin une côte basse et verte.","Mercredi 16 mars. Nous jetons l’ancre. Un peuple inconnu nous attend sur la plage : je n’ai jamais vu d’hommes si grands. Leurs maisons, longues comme une halle, abritent des dizaines de familles.","Vendredi 18 mars. Étrange pays ! Les arbres portent des fruits jamais vus chez nous, et les oiseaux sont des merveilles de couleurs. J’en ai compté vingt sortes.","Samedi 19 mars. Un petit animal court devant mes pieds : il est gros comme un lièvre, mais il marche sur deux pattes."],"source":"Journal imaginé pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre mots** qui montrent que le marin dit « je » (pronoms et déterminants de la première personne).","aide":"Cherche j’, je, J’ et un mot qui veut dire « les miens ».","type":"zone","document":"carnet","multiple":true},{"enonce":"Touche les **trois expressions** du vocabulaire de l’étonnement.","aide":"Le marin est surpris : cherche ce qu’il n’avait jamais vu, ce qui est bizarre, ce qui est extraordinaire.","type":"zone","document":"carnet","multiple":true},{"enonce":"Pour faire imaginer l’inconnu, le marin le compare à ce qu’il connaît. Touche les **deux comparaisons**.","aide":"Une comparaison utilise « comme » pour rapprocher deux choses.","type":"zone","document":"carnet","multiple":true},{"enonce":"Pourquoi le marin donne-t-il des dates et des nombres (« six semaines », « vingt sortes ») ?","aide":"Un voyageur raconte des choses que personne n’a vues : que cherche-t-il à obtenir ?","type":"choix","options":[{"id":"a","texte":"Pour cacher une partie de la vérité"},{"id":"b","texte":"Pour amuser ses lecteurs"},{"id":"c","texte":"Pour être cru de ses lecteurs"},{"id":"d","texte":"Pour remplir des pages vides"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m31","m73","m87"]},"explication":"Les marques du narrateur sont **j’**, **je**, **J’** et **mes** : le voyageur dit « je » et se porte garant de ce qu’il raconte."},{"cle":{"type":"zone","ids":["m54","m61","m62","m70"]},"explication":"**Étrange**, **jamais vus** et **merveilles** disent la surprise du voyageur devant l’inconnu."},{"cle":{"type":"zone","ids":["m42","m43","m44","m45","m91","m92","m93","m94"]},"explication":"Les deux comparaisons sont **longues comme une halle** et **gros comme un lièvre** : l’inconnu est dit avec des mots du connu."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le voyageur veut être **cru** : il multiplie les détails précis, les dates et les mesures."}]$ex$::jsonb),
  ('8f784bec-0277-5d05-b70e-7d47fb81e7bc'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Qui a raconté quoi ?","competence":"analyser-document","situation":"Pour son exposé sur les grands voyageurs, Emma a dressé un tableau. Elle échange ensuite avec Tom, qui a lu le même tableau… mais qui glisse une erreur dans sa phrase.","documents":[{"id":"voyageurs","type":"tableau","titre":"Quatre textes de voyage","colonnes":["Auteur","Texte","Date"],"lignes":[["Marco Polo","Le Devisement du monde","vers 1298"],["Christophe Colomb","Journal de bord","1492"],["Jean de Léry","Histoire d’un voyage en terre de Brésil","1578"],["Michel de Montaigne","« Des cannibales » (Essais)","1580"]],"enteteLignes":true,"source":"Dates d’après le cours"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Les messages d’Emma et de Tom","participants":[{"nom":"Emma","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Emma","texte":"Pour l’exposé, je prends les quatre auteurs du tableau."},{"qui":"Tom","texte":"Super ! Moi je dirai que Jean de Léry raconte son voyage en Chine, comme Marco Polo."}]}],"questions":[{"enonce":"Combien d’années séparent le journal de bord de Colomb du livre de Jean de Léry ?","aide":"Soustrais les deux dates du tableau.","type":"nombre","unite":"ans"},{"enonce":"Dans le tableau, touche le texte qui est un texte administratif devenu document historique.","aide":"Il est tenu au jour le jour à bord d’un navire.","type":"zone","document":"voyageurs","multiple":false},{"enonce":"Tom se trompe. Touche les mots fautifs de sa phrase en relisant le tableau.","aide":"Regarde le titre de l’œuvre de Léry dans le tableau : de quel pays parle-t-il ?","type":"zone","document":"sms","multiple":true},{"enonce":"Relie chaque voyageur à ce qu’il a fait.","aide":"Pense au lieu où Marco Polo a mis ses souvenirs par écrit, et au mot « sauvage ».","type":"association","gauche":[{"id":"g0","texte":"Marco Polo"},{"id":"g1","texte":"Christophe Colomb"},{"id":"g2","texte":"Jean de Léry"},{"id":"g3","texte":"Montaigne"}],"droite":[{"id":"d0","texte":"Invente la figure du « bon sauvage »"},{"id":"d1","texte":"Dicte ses voyages en prison"},{"id":"d2","texte":"Tient un journal de bord"},{"id":"d3","texte":"Porte un regard d’ethnographe sur le Brésil"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":86,"tolerance":0},"affichage":"86 ans","explication":"De 1492 à 1578, il y a 1578 − 1492 = **86 ans**."},{"cle":{"type":"zone","ids":["r1c1"]},"explication":"C’est le **journal de bord** de Christophe Colomb (1492), à l’origine un texte administratif."},{"cle":{"type":"zone","ids":["m21","m22"]},"explication":"Léry parle du **Brésil** (*Histoire d’un voyage en terre de Brésil*, 1578), pas de la Chine : le voyage en Chine est celui de Marco Polo."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g1":"d2","g2":"d3"}},"explication":"Marco Polo dicte son livre en **prison** ; Colomb tient son **journal de bord** ; Léry est l’un des premiers **ethnographes** ; Montaigne invente le **« bon sauvage »**."}]$ex$::jsonb),
  ('8f784bec-0277-5d05-b70e-7d47fb81e7bc'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Trois routes, trois regards","competence":"se-reperer-espace","situation":"Un professeur affiche une carte de trois grands voyages et deux témoignages sur un même peuple lointain. Il demande à ses élèves de situer, de dater et de reconnaître le regard de chaque voyageur.","documents":[{"id":"carte","type":"carte","titre":"Trois voyages célèbres","fond":"monde","cadrage":[-100,-35,155,60],"regionsCliquables":true,"lieux":[{"id":"z1","lon":-43.2,"lat":-22.9,"nom":"Léry, 1578","symbole":"carre","teinte":"corail"}],"traits":[{"id":"z2","points":["venise","pekin"],"style":"fleche","teinte":"ambre","epaisseur":2,"etiquette":"Marco Polo, vers 1298"},{"id":"z3","points":[[-6.9,37.2],[-74.5,24.1]],"style":"fleche","teinte":"bleu","epaisseur":2,"etiquette":"Colomb, 1492"}],"source":"Trajets simplifiés"},{"id":"regards","type":"texte","genre":"recit","titre":"Deux voyageurs, un même peuple","blocs":["Voyageur A : « Quelle merveille ! Ces hommes lisent le ciel et les rivières mieux que nos pilotes. J’admire leurs chants. »","Voyageur B : « Ces gens sont des barbares : ils vivent sans lois, comme des bêtes. Il faut leur apprendre à vivre. »"],"source":"Textes écrits pour l’exercice"}],"questions":[{"enonce":"Le journal de bord de 1492 raconte la traversée de l’océan Atlantique. Touche ce trajet sur la carte.","aide":"Cherche la flèche qui va de l’Europe vers l’Amérique.","type":"zone","document":"carte","multiple":false},{"enonce":"Range les trois voyageurs de la carte du plus ancien au plus récent.","aide":"Lis les dates écrites sur la carte.","type":"ordre","items":[{"id":"a","texte":"Christophe Colomb"},{"id":"b","texte":"Jean de Léry"},{"id":"c","texte":"Marco Polo"}]},{"enonce":"Touche les deux expressions qui montrent le **mépris** du voyageur B.","aide":"Cherche les mots par lesquels il rabaisse les habitants.","type":"zone","document":"regards","multiple":true},{"enonce":"Que révèlent les deux textes sur les récits de voyage ?","aide":"Le même peuple est décrit de deux façons opposées : qui change d’un texte à l’autre ?","type":"choix","options":[{"id":"a","texte":"Le voyageur regarde toujours depuis sa propre culture"},{"id":"b","texte":"Le voyageur n’invente jamais rien"},{"id":"c","texte":"Le voyageur ne parle jamais de lui-même"},{"id":"d","texte":"Le voyageur décrit toujours exactement ce qu’il voit"}],"multiple":false},{"enonce":"Complète ce que fait Montaigne dans « Des cannibales ».","aide":"Il met en scène un peuple lointain vertueux pour juger son pays.","type":"trous","segments":["Montaigne invente la figure du « ",0," » pour critiquer sa propre ",1,"."],"banque":["voyageur","bon sauvage","société","navigateur","prison"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"C’est la flèche **Colomb, 1492** : de l’Espagne vers les îles de l’Atlantique, de l’autre côté de l’océan."},{"cle":{"type":"ordre","ids":["c","a","b"]},"explication":"Dans l’ordre : **Marco Polo** (vers 1298), **Christophe Colomb** (1492), **Jean de Léry** (1578)."},{"cle":{"type":"zone","ids":["m25","m26","m31","m32","m33"]},"explication":"**des barbares** et **comme des bêtes** : le voyageur B juge les habitants depuis sa propre culture, avec mépris."},{"cle":{"type":"choix","ids":["a"]},"explication":"Les deux voyageurs voient le même peuple, mais chacun parle **depuis sa propre culture** : le récit en dit autant sur celui qui regarde que sur ce qu’il regarde."},{"cle":{"type":"trous","trous":[["bon sauvage"],["societe","sa societe"]]},"affichage":"bon sauvage · société","explication":"Montaigne invente le **« bon sauvage »** pour critiquer **sa propre société**."}]$ex$::jsonb),
  ('4366ab9b-8872-567d-bf24-2f2eb9c1a9ea'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un pays qui n’existe pas","competence":"analyser-texte","situation":"Le club de poésie lit les premiers vers d’un célèbre poème d’invitation au voyage. Sam veut repérer comment le poète s’adresse à quelqu’un et comment il fait rêver d’un ailleurs.","documents":[{"id":"invitation","type":"texte","genre":"poeme","titre":"L’Invitation au voyage","blocs":["Mon enfant, ma sœur,","Songe à la douceur","D’aller là-bas vivre ensemble !","Aimer à loisir,","Aimer et mourir","Au pays qui te ressemble !","","Là, tout n’est qu’ordre et beauté,","Luxe, calme et volupté."],"auteur":"Charles Baudelaire","source":"Baudelaire, Les Fleurs du mal (1857) : les six premiers vers, puis le refrain"}],"questions":[{"enonce":"Touche les mots par lesquels le poète s’adresse directement à quelqu’un.","aide":"Une apostrophe interpelle une personne : cherche-la au tout début.","type":"zone","document":"invitation","multiple":true},{"enonce":"Touche le verbe à l’**impératif** qui sert à inviter.","aide":"C’est un ordre doux, au début du deuxième vers.","type":"zone","document":"invitation","multiple":true},{"enonce":"Touche le mot qui montre que le bonheur est ailleurs.","aide":"Cherche un mot de lieu, dans le troisième vers.","type":"zone","document":"invitation","multiple":true},{"enonce":"Pourquoi les mêmes vers reviennent-ils (le refrain) à la fin des strophes ?","aide":"Pense à un air que l’on répète pour bercer.","type":"choix","options":[{"id":"a","texte":"Parce que le poète n’a plus d’idées"},{"id":"b","texte":"Pour décrire une carte très précise"},{"id":"c","texte":"Pour donner des informations utiles"},{"id":"d","texte":"Pour imiter le bercement du départ"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m1","m2","m3"]},"explication":"**Mon enfant, ma sœur** est une apostrophe : le poète parle à la personne qu’il invite."},{"cle":{"type":"zone","ids":["m4"]},"explication":"**Songe** est à l’impératif : il invite la personne aimée à rêver avec lui."},{"cle":{"type":"zone","ids":["m10"]},"explication":"**là-bas** désigne un ailleurs lointain : c’est la promesse du voyage."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le rythme et le refrain créent une **musicalité** qui imite le bercement du départ."}]$ex$::jsonb),
  ('4366ab9b-8872-567d-bf24-2f2eb9c1a9ea'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Heureux qui, comme Ulysse…","competence":"analyser-texte","situation":"Joachim du Bellay est à Rome, loin de chez lui. Léa lit deux passages d’un de ses sonnets et complète un tableau qui range les poètes selon leur façon de voyager.","documents":[{"id":"regrets","type":"texte","genre":"poeme","titre":"Les Regrets, sonnet 31","blocs":["Heureux qui, comme Ulysse, a fait un beau voyage,","(…)","Quand reverrai-je, hélas, de mon petit village","Fumer la cheminée, et en quelle saison"],"auteur":"Joachim du Bellay","source":"Du Bellay, Les Regrets (1558), vers 1, 5 et 6, orthographe modernisée"},{"id":"facons","type":"tableau","titre":"Trois façons de traiter le voyage","colonnes":["La façon","Le poète","Ce qu’il en fait"],"lignes":[["Le voyage rêvé","Baudelaire","Un pays fait du désir du poète"],["Le voyage comme fuite","Rimbaud","Fuir l’ennui, la médiocrité, soi-même"],["Le retour et le regret","Du Bellay","Le mal du pays, écrit depuis Rome"]],"enteteLignes":true,"source":"D’après le cours"}],"questions":[{"enonce":"Touche le nom du héros antique auquel le poète se compare.","aide":"C’est le héros de l’*Odyssée*, qui met dix ans à rentrer chez lui.","type":"zone","document":"regrets","multiple":true},{"enonce":"Touche l’interjection par laquelle le poète exprime sa plainte.","aide":"Elle est au début du vers 5, entre deux virgules.","type":"zone","document":"regrets","multiple":true},{"enonce":"Que regrette Du Bellay depuis Rome ?","aide":"Relis le vers 5 : de quoi parle-t-il avec tendresse ?","type":"choix","options":[{"id":"a","texte":"Une longue guerre qu’il a perdue"},{"id":"b","texte":"Un voyage qu’il n’a jamais osé faire"},{"id":"c","texte":"Les palais de Rome qu’il a dû quitter"},{"id":"d","texte":"Son petit village, où il rêve de rentrer"}],"multiple":false},{"enonce":"Touche, dans le tableau, la façon de voyager que ce sonnet illustre.","aide":"Le poète est loin de chez lui et rêve de rentrer.","type":"zone","document":"facons","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**Ulysse** est le modèle du voyageur qui rentre : Du Bellay rêve de son propre retour."},{"cle":{"type":"zone","ids":["m11"]},"explication":"**hélas** est un cri de plainte : le poète regrette son village."},{"cle":{"type":"choix","ids":["d"]},"explication":"Il regrette son **petit village** : il le préfère aux palais romains."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"Le sonnet de Du Bellay relève du **retour et du regret** : le mal du pays, écrit depuis Rome."}]$ex$::jsonb),
  ('4366ab9b-8872-567d-bf24-2f2eb9c1a9ea'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Samarcande, Zanzibar, Tombouctou","competence":"analyser-texte","situation":"Pour la fête de fin d’année, Noé a écrit un petit poème de départ. Avant de le lire, il le soumet à un tableau qui range les façons de voyager en poésie.","documents":[{"id":"depart","type":"texte","genre":"poeme","titre":"Départ","blocs":["Ô mer, berce mon départ !","Samarcande, Zanzibar, Tombouctou :","ces noms sonnent comme des cloches lointaines.","Sable, soie, épices, étoiles,","tout défile derrière mes paupières.","Je pars, mais je veux rentrer, comme Ulysse."],"source":"Poème écrit pour l’exercice"},{"id":"facons2","type":"tableau","titre":"Trois façons de voyager en poésie","colonnes":["La façon","Ce qu’elle dit"],"lignes":[["Le voyage rêvé","Un pays fait du désir du poète"],["Le voyage comme fuite","Fuir l’ennui, la médiocrité, soi-même"],["Le retour et le regret","Le voyageur est un homme qui rentre"]],"enteteLignes":true,"source":"D’après le cours"}],"questions":[{"enonce":"Touche les **trois noms propres exotiques**, qui font rêver par leur seule sonorité.","aide":"Ce sont des noms de villes lointaines, avec une majuscule.","type":"zone","document":"depart","multiple":true},{"enonce":"Touche les **quatre mots** de l’énumération qui fait défiler les merveilles entrevues.","aide":"Ils se suivent, séparés par des virgules, au quatrième vers.","type":"zone","document":"depart","multiple":true},{"enonce":"Touche la comparaison qui transforme les noms en musique.","aide":"Cherche le mot « comme » au troisième vers.","type":"zone","document":"depart","multiple":true},{"enonce":"Relie chaque procédé à son effet.","aide":"Pense à ce que le lecteur éprouve en lisant chaque procédé.","type":"association","gauche":[{"id":"g0","texte":"Énumération"},{"id":"g1","texte":"Noms propres exotiques"},{"id":"g2","texte":"Apostrophe"},{"id":"g3","texte":"Refrain"}],"droite":[{"id":"d0","texte":"Le poète s’adresse à quelqu’un ou à quelque chose"},{"id":"d1","texte":"Il imite le bercement du départ"},{"id":"d2","texte":"Les merveilles entrevues défilent"},{"id":"d3","texte":"Ils font rêver par leur sonorité"}]},{"enonce":"La dernière ligne du poème rappelle Ulysse. Touche, dans le tableau, la façon de voyager qu’elle annonce.","aide":"Ulysse est celui qui rentre chez lui.","type":"zone","document":"facons2","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m6","m7"]},"explication":"**Samarcande**, **Zanzibar** et **Tombouctou** font rêver par leur seule musique."},{"cle":{"type":"zone","ids":["m15","m16","m17","m18"]},"explication":"**Sable, soie, épices, étoiles** : l’énumération fait défiler les merveilles."},{"cle":{"type":"zone","ids":["m11","m12","m13","m14"]},"explication":"**comme des cloches lointaines** compare les noms à des sons qui font rêver."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"Chaque procédé a son effet : l’**énumération** fait défiler, les **noms propres** font rêver, l’**apostrophe** interpelle, le **refrain** berce."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"Le poème se termine par le désir de rentrer, **comme Ulysse** : c’est le thème du **retour**, car depuis l’*Odyssée* le voyageur poétique est un homme qui rentre."}]$ex$::jsonb),
  ('6c916708-6b4d-586a-bacf-4aaff6a2264f'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Tom embarque sur le Dauphin","competence":"analyser-texte","situation":"Le professeur distribue le début d’un roman d’aventures inventé pour la classe. Il faut repérer qui raconte, les épreuves du héros et le moment où le suspense s’installe.","documents":[{"id":"dauphin","type":"texte","genre":"recit","titre":"Le début d’un roman","blocs":["Je m’appelle Tom et j’ai treize ans. Hier, j’ai quitté mon village pour embarquer sur le *Dauphin*, un voilier qui part chercher un trésor.","Le troisième jour, une tempête a brisé notre mât. Le capitaine Brook a hurlé : « À l’abri ! »","Cette nuit-là, le cuisinier nous a trahis : il a volé la carte au trésor.","Une semaine plus tard, nous avons échoué sur une île déserte.","Soudain, une ombre se glisse derrière moi… Qui est-ce ?"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Qui raconte l’histoire ?","aide":"Le texte commence par « Je m’appelle Tom ».","type":"choix","options":[{"id":"a","texte":"Un narrateur extérieur qui connaît tout"},{"id":"b","texte":"Le cuisinier, qui s’explique à la fin"},{"id":"c","texte":"Tom lui-même : le narrateur est interne"},{"id":"d","texte":"Le capitaine Brook, qui observe le héros"}],"multiple":false},{"enonce":"Touche les **deux péripéties** (épreuves ou coups durs) de l’histoire.","aide":"Cherche un phénomène de la nature et une trahison.","type":"zone","document":"dauphin","multiple":true},{"enonce":"Touche la phrase qui entretient le suspense à la fin du passage.","aide":"Elle pose une question qui reste sans réponse.","type":"zone","document":"dauphin","multiple":true},{"enonce":"Range ces événements dans l’ordre du récit.","aide":"Les jours sont comptés dans le texte : « le troisième jour », « cette nuit-là », « une semaine plus tard ».","type":"ordre","items":[{"id":"a","texte":"La tempête brise le mât"},{"id":"b","texte":"Le cuisinier vole la carte"},{"id":"c","texte":"Tom embarque"},{"id":"d","texte":"Le bateau échoue sur une île"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"Tom dit « je » : le **narrateur est interne**, ce qui rapproche le lecteur du héros."},{"cle":{"type":"zone","ids":["m30","m31","m46","m47","m48","m49","m50"]},"explication":"Les péripéties sont **une tempête** et **le cuisinier nous a trahis**."},{"cle":{"type":"zone","ids":["m76","m77"]},"explication":"**Qui est-ce ?** : la fin du chapitre laisse une question en suspens, ce qui donne envie de lire la suite."},{"cle":{"type":"ordre","ids":["c","a","b","d"]},"explication":"Tom **embarque**, la **tempête** brise le mât, le **cuisinier vole la carte**, puis le bateau **échoue** sur l’île."}]$ex$::jsonb),
  ('6c916708-6b4d-586a-bacf-4aaff6a2264f'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Vite ou lentement ?","competence":"analyser-texte","situation":"Dans un roman d’aventures, l’auteur règle la vitesse du récit comme un conducteur : il accélère dans le danger, il ralentit pour faire voir. Léna observe ce réglage dans un passage inventé.","documents":[{"id":"vitesses","type":"texte","genre":"recit","titre":"Le Cormoran","blocs":["« Hisse la voile ! cria Brook. — Oui, capitaine ! » répondit Tom en tirant sur la corde de toutes ses forces.","Pendant dix jours, il ne se passa rien d’autre que le vent, les vagues et les repas de biscuit.","La plage s’étendait, longue et blanche, bordée de palmiers dont les feuilles ne bougeaient pas.","Trois ans plus tard, Tom revint au village, devenu un homme."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le passage qui résume **dix jours** en une phrase : c’est un sommaire.","aide":"Cherche une longue durée racontée très vite.","type":"zone","document":"vitesses","multiple":true},{"enonce":"Touche le passage où l’action s’arrête pour décrire un paysage : c’est une pause.","aide":"Plus rien ne se passe : on regarde.","type":"zone","document":"vitesses","multiple":true},{"enonce":"Touche les mots qui annoncent un passage de temps passé sous silence : c’est une ellipse.","aide":"Cherche une durée de plusieurs années.","type":"zone","document":"vitesses","multiple":true},{"enonce":"Relie chaque vitesse du récit à ce qu’elle fait.","aide":"Pense au premier paragraphe : un dialogue à voix haute.","type":"association","gauche":[{"id":"g0","texte":"Scène"},{"id":"g1","texte":"Sommaire"},{"id":"g2","texte":"Ellipse"},{"id":"g3","texte":"Pause"}],"droite":[{"id":"d0","texte":"Le récit prend le temps de l’action, dialogue compris"},{"id":"d1","texte":"Un passage de temps passé sous silence"},{"id":"d2","texte":"Une description qui suspend l’action"},{"id":"d3","texte":"Plusieurs jours résumés en quelques lignes"}]},{"enonce":"Pourquoi un roman d’aventures alterne-t-il ces vitesses ?","aide":"Réfléchis aux moments de danger et aux moments de calme.","type":"choix","options":[{"id":"a","texte":"Il ralentit seulement quand le héros est en danger"},{"id":"b","texte":"Il ne fait jamais de description pour aller plus vite"},{"id":"c","texte":"Il accélère dans le danger et ralentit pour faire voir"},{"id":"d","texte":"Il garde toujours la même vitesse du début à la fin"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18","m19","m20","m21","m22","m23","m24","m25","m26","m27","m28","m29","m30","m31","m32","m33","m34","m35","m36","m37"]},"explication":"**Pendant dix jours…** : plusieurs jours sont résumés en quelques lignes, c’est un **sommaire**."},{"cle":{"type":"zone","ids":["m38","m39","m40","m41","m42","m43","m44","m45","m46","m47","m48","m49","m50","m51","m52","m53"]},"explication":"La description de la plage suspend l’action : c’est une **pause**."},{"cle":{"type":"zone","ids":["m54","m55","m56","m57"]},"explication":"**Trois ans plus tard** : tout ce qui s’est passé pendant ce temps est **passé sous silence**, c’est une **ellipse**."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"La **scène** montre l’action en direct, le **sommaire** résume, l’**ellipse** saute, la **pause** décrit."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le roman d’aventures **alterne** les vitesses : il accélère dans le danger et ralentit pour faire voir."}]$ex$::jsonb),
  ('6c916708-6b4d-586a-bacf-4aaff6a2264f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La quatrième de couverture de Léo","competence":"analyser-document","situation":"La libraire a affiché la quatrième de couverture d’un roman inventé, *L’Île aux Sept Courants*. À côté, une petite affiche présente quelques grands romans d’aventures. Tu dois lire l’une avec l’autre.","documents":[{"id":"couv","type":"fiche","modele":"affiche","entete":"L’Île aux Sept Courants","sousTitre":"Un roman d’aventures","emoji":"🏝️","teinte":"bleu","lignes":[{"texte":"Léo, douze ans, rêve de partir en mer.","id":"z1"},{"texte":"Un matin, il embarque en cachette sur le *Cormoran*.","id":"z2"},{"texte":"Tempête, naufrage, trahison : rien ne lui sera épargné.","id":"z3"},{"texte":"« Je n’oublierai jamais cette nuit-là », raconte-t-il.","id":"z4"},{"texte":"Un an plus tard, il revient au village… et personne ne le reconnaît.","id":"z5"}],"pied":"Quatrième de couverture inventée pour l’exercice"},{"id":"rayon","type":"fiche","modele":"affiche","entete":"Rayon aventures","sousTitre":"Les grands titres","emoji":"📚","teinte":"violet","lignes":[{"texte":"Robinson Crusoé","valeur":"1719"},{"texte":"L’Île au trésor","valeur":"1883"},{"texte":"Vingt mille lieues sous les mers","valeur":"Jules Verne"}],"pied":"D’après le cours"}],"questions":[{"enonce":"Touche la ligne qui annonce les péripéties du roman.","aide":"Cherche une phrase qui énumère des coups durs.","type":"zone","document":"couv","multiple":false},{"enonce":"Touche la ligne qui montre que le héros est transformé à la fin.","aide":"Après un an, que se passe-t-il quand il rentre chez lui ?","type":"zone","document":"couv","multiple":false},{"enonce":"À quelle citation voit-on que le narrateur est interne ?","aide":"Cherche une phrase où le héros dit « je ».","type":"choix","options":[{"id":"a","texte":"Tempête, naufrage, trahison : rien ne l’arrête"},{"id":"b","texte":"« Je n’oublierai jamais cette nuit-là »"},{"id":"c","texte":"Un matin, il embarque en cachette"},{"id":"d","texte":"Léo, douze ans, rêve de partir en mer"}],"multiple":false},{"enonce":"Combien d’années séparent *Robinson Crusoé* de *L’Île au trésor* ?","aide":"Utilise l’affiche du rayon aventures.","type":"nombre","unite":"ans"},{"enonce":"Pourquoi dit-on que ce roman est un récit d’apprentissage ?","aide":"Compare Léo au début (douze ans, il rêve) et à la fin (personne ne le reconnaît).","type":"choix","options":[{"id":"a","texte":"Le héros part enfant et revient adulte, construit par les épreuves"},{"id":"b","texte":"Le héros raconte surtout ce qu’il a lu dans des livres"},{"id":"c","texte":"Le héros apprend des leçons dans un manuel scolaire"},{"id":"d","texte":"Le héros reste le même du début à la fin du roman"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"**Tempête, naufrage, trahison** : ce sont les péripéties qui vont éprouver le héros."},{"cle":{"type":"zone","ids":["z5"]},"explication":"**Personne ne le reconnaît** : Léo est parti enfant et revient changé, comme dans un récit d’apprentissage."},{"cle":{"type":"choix","ids":["b"]},"explication":"Léo dit **« je »** : c’est lui qui raconte, le narrateur est interne."},{"cle":{"type":"nombre","valeur":164,"tolerance":0},"affichage":"164 ans","explication":"De 1719 à 1883, il y a 1883 − 1719 = **164 ans**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Léo part enfant et revient **transformé** : l’île et la mer sont les épreuves qui le **construisent**."}]$ex$::jsonb),
  ('fde4fddf-3208-557a-829e-0de6fa170325'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Horace confie ses secrets à Arnolphe","competence":"analyser-texte","situation":"La troupe du collège joue une scène écrite dans l’esprit de *L’École des femmes*, de Molière. Horace raconte son bonheur à un homme qui, sans qu’il le sache, est son rival. Le public rit : à toi de comprendre pourquoi.","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"Une place de la ville","blocs":[{"didascalie":"Horace raconte sa journée à Arnolphe, qui l’écoute avec un sourire forcé."},{"personnage":"Horace","replique":"Monsieur, je suis fou d’amour pour une jeune fille ! Son tuteur la tient enfermée, mais j’ai trouvé le moyen de lui parler."},{"personnage":"Arnolphe (à part)","replique":"Quel supplice ! Cet imbécile ne sait pas qui je suis…"},{"personnage":"Horace","replique":"Elle m’a souri ce matin ! Je suis le plus heureux des hommes."}],"source":"Scène écrite pour l’exercice, dans l’esprit de Molière"}],"questions":[{"enonce":"Pourquoi cette scène fait-elle rire le public ?","aide":"Qui est le tuteur dont parle Horace ? Et qui l’écoute ?","type":"choix","options":[{"id":"a","texte":"Horace se déguise en vieillard pour tromper son tuteur"},{"id":"b","texte":"Arnolphe raconte une histoire drôle à tout le village"},{"id":"c","texte":"Horace confie ses progrès à son rival sans le savoir"},{"id":"d","texte":"Arnolphe tombe de sa chaise devant tout le monde"}],"multiple":false},{"enonce":"Touche les mots qui montrent qu’Arnolphe souffre en secret.","aide":"Cherche la réplique dite « à part », que seul le public entend.","type":"zone","document":"scene","multiple":true},{"enonce":"Touche le mot de la didascalie qui montre que le sourire d’Arnolphe n’est pas sincère.","aide":"Cherche un adjectif accolé à « sourire ».","type":"zone","document":"scene","multiple":true}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"Le public sait qu’Arnolphe est le tuteur, mais Horace l’ignore : c’est le **comique de situation**."},{"cle":{"type":"zone","ids":["m37","m38"]},"explication":"**Quel supplice** : Arnolphe cache sa souffrance à Horace, mais le public l’entend."},{"cle":{"type":"zone","ids":["m12"]},"explication":"Le sourire est **forcé** : Arnolphe cache sa jalousie."}]$ex$::jsonb),
  ('fde4fddf-3208-557a-829e-0de6fa170325'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le théâtre se défend par le théâtre","competence":"analyser-document","situation":"En 1662, *L’École des femmes* fait scandale. Un journal imaginaire de la classe résume l’histoire de la pièce, puis explique la réponse de Molière à ses accusateurs.","documents":[{"id":"intrigue","type":"chaine","titre":"L’intrigue de la pièce","disposition":"colonne","noeuds":[{"id":"z1","texte":"Arnolphe élève Agnès dans l’ignorance"},{"id":"z2","texte":"Il l’aime et compte l’épouser"},{"id":"z3","texte":"Agnès rencontre le jeune Horace"},{"id":"z4","texte":"Horace raconte tout à son rival sans le savoir"}],"liens":[{"de":"z1","a":"z2","texte":"puis"},{"de":"z2","a":"z3","texte":"mais"},{"de":"z3","a":"z4","texte":"et"}]},{"id":"querelle","type":"texte","genre":"article","titre":"Une querelle célèbre","blocs":["Après la première, certains spectateurs accusent Molière d’immoralité.","Il ne publie pas de lettre de défense : il répond par deux pièces, La Critique de l’École des femmes et L’Impromptu de Versailles."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche l’étape qui crée l’ironie qui structure la pièce.","aide":"Cherche l’étape où quelqu’un parle sans savoir à qui.","type":"zone","document":"intrigue","multiple":false},{"enonce":"Touche les **deux titres** des pièces par lesquelles Molière répond à ses accusateurs.","aide":"Les titres sont écrits en entier, après « deux pièces ».","type":"zone","document":"querelle","multiple":true},{"enonce":"Touche le reproche fait à Molière après la première.","aide":"C’est un nom abstrait : on lui reproche de manquer de morale.","type":"zone","document":"querelle","multiple":true},{"enonce":"Pourquoi Arnolphe n’est-il pas un simple personnage de farce ?","aide":"Relis l’étape 2 de l’intrigue.","type":"choix","options":[{"id":"a","texte":"Parce qu’il ne dit jamais rien de drôle"},{"id":"b","texte":"Parce qu’il gagne à la fin de la pièce"},{"id":"c","texte":"Parce qu’il aime réellement Agnès"},{"id":"d","texte":"Parce qu’il est un jeune premier"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"C’est l’étape où **Horace raconte ses progrès à Arnolphe**, sans savoir qu’il parle à son rival."},{"cle":{"type":"zone","ids":["m22","m23","m24","m25","m26","m27","m28","m30","m31","m32","m33"]},"explication":"Molière répond par **La Critique de l’École des femmes** et **L’Impromptu de Versailles**."},{"cle":{"type":"zone","ids":["m8"]},"explication":"On reproche à Molière son **immoralité**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Arnolphe **aime réellement** Agnès : il échoue et reste seul, ce qui dépasse la simple farce."}]$ex$::jsonb),
  ('fde4fddf-3208-557a-829e-0de6fa170325'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Agnès a appris à penser","competence":"analyser-texte","situation":"Dans cette scène inventée, Agnès répond à son tuteur avec une vivacité qui le surprend. Un tableau rappelle les trois grandes questions que la pièce met en jeu.","documents":[{"id":"agnes","type":"texte","genre":"theatre","titre":"Dans le jardin d’Arnolphe","blocs":[{"personnage":"Arnolphe","replique":"Je vous ai élevée dans l’ignorance pour votre bien. Une femme n’a pas besoin d’en savoir plus."},{"personnage":"Agnès","replique":"Pourtant, Monsieur, hier j’ai compris toute seule ce que vous me cachiez."},{"personnage":"Arnolphe","replique":"Qui vous a appris à parler ainsi ?"},{"personnage":"Agnès","replique":"L’amour, Monsieur. Il m’a rendue plus savante que tous vos livres."},{"personnage":"Arnolphe (seul)","replique":"Mon plan s’effondre : j’aime Agnès et je la perds."}],"source":"Scène écrite pour l’exercice, dans l’esprit de Molière"},{"id":"enjeux","type":"tableau","titre":"Ce que la pièce met en jeu","colonnes":["La question","Ce qu’elle pose"],"lignes":[["L’éducation des filles","Faut-il les instruire, ou les tenir dans l’ignorance ?"],["Le mariage forcé","L’autorité des tuteurs"],["La liberté","Choisir sa vie"]],"enteteLignes":true,"source":"D’après le cours"}],"questions":[{"enonce":"La première réplique d’Arnolphe parle d’instruire ou non une femme. Touche la question du tableau qu’elle illustre.","aide":"Il décide ce qu’Agnès a le droit de savoir.","type":"zone","document":"enjeux","multiple":false},{"enonce":"Touche les mots qui montrent qu’Agnès a appris à raisonner toute seule.","aide":"Cherche ce qu’elle dit avoir fait « hier ».","type":"zone","document":"agnes","multiple":true},{"enonce":"Que montre l’évolution d’Agnès sur l’éducation ?","aide":"Agnès dit qu’elle est devenue plus savante : grâce à quoi ?","type":"choix","options":[{"id":"a","texte":"Seuls les livres suffisent à rendre intelligent"},{"id":"b","texte":"Les filles n’ont aucun besoin d’apprendre à lire"},{"id":"c","texte":"Un tuteur sait toujours mieux que sa pupille ce qui est bon"},{"id":"d","texte":"C’est l’ignorance, et non la nature, qui l’enfermait"}],"multiple":false},{"enonce":"Touche les mots qui montrent qu’Arnolphe n’est pas seulement ridicule : il souffre vraiment.","aide":"Cherche ce qu’il avoue à la dernière réplique.","type":"zone","document":"agnes","multiple":true}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0"]},"explication":"La réplique d’Arnolphe porte sur **l’éducation des filles** : faut-il les instruire ou les tenir dans l’ignorance ?"},{"cle":{"type":"zone","ids":["m25","m26","m27"]},"explication":"**compris toute seule** montre qu’Agnès pense par elle-même."},{"cle":{"type":"choix","ids":["d"]},"explication":"Agnès devient intelligente en devenant amoureuse : c’est **l’ignorance** qui la tenait enfermée, pas sa nature."},{"cle":{"type":"zone","ids":["m57","m58","m59"]},"explication":"**j’aime Agnès** : Arnolphe aime réellement, et c’est ce qui rend la pièce plus profonde qu’une farce."}]$ex$::jsonb),
  ('6599efec-fefb-5c60-86a9-b028fa4f86ed'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un été au bout du chemin","competence":"analyser-texte","situation":"Une romancière imaginaire raconte un été de son enfance. Dans ce court extrait, on entend deux voix : l’adulte qui écrit aujourd’hui et la petite fille qui ne savait pas encore.","documents":[{"id":"ete","type":"texte","genre":"recit","titre":"Extrait de souvenirs","blocs":["Quand j’avais huit ans, nous habitions une maison au bout d’un chemin de terre. Chaque été, mon grand-père réparait ses filets dans la cour.","L’odeur de goudron et le cri des mouettes me reviennent encore, intacts.","Ce jour-là, je ne savais pas encore que c’était notre dernier été."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux sensations** (une odeur, un son) qui font revenir le souvenir.","aide":"Un souvenir revient plus sûrement par les sens que par les faits.","type":"zone","document":"ete","multiple":true},{"enonce":"Touche les **deux verbes à l’imparfait** qui décrivent le décor et les habitudes.","aide":"Ils disent ce qui se passait chaque été.","type":"zone","document":"ete","multiple":true},{"enonce":"Touche les mots par lesquels l’adulte annonce ce qu’il sait déjà.","aide":"C’est une anticipation : la voix de l’adulte sait la suite.","type":"zone","document":"ete","multiple":true},{"enonce":"Qui annonce que c’était « notre dernier été » ?","aide":"L’enfant ne savait pas : qui le sait donc ?","type":"choix","options":[{"id":"a","texte":"L’adulte qui écrit (le je narrant)"},{"id":"b","texte":"Le grand-père, qui le dit à voix haute"},{"id":"c","texte":"L’enfant de huit ans (le je narré)"},{"id":"d","texte":"Un narrateur extérieur à l’histoire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m26","m27","m28","m29","m31","m32","m33","m34"]},"explication":"**L’odeur de goudron** et **le cri des mouettes** sont des sensations qui ravivent le souvenir."},{"cle":{"type":"zone","ids":["m6","m20"]},"explication":"**habitions** et **réparait** sont à l’imparfait : ce temps sert au décor et aux habitudes."},{"cle":{"type":"zone","ids":["m41","m42","m43","m44","m45"]},"explication":"**je ne savais pas encore** est une anticipation : l’adulte qui écrit sait ce que l’enfant ignorait."},{"cle":{"type":"choix","ids":["a"]},"explication":"C’est le **je narrant**, l’adulte qui écrit et qui sait ce qui va arriver."}]$ex$::jsonb),
  ('6599efec-fefb-5c60-86a9-b028fa4f86ed'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Autobiographie, roman ou autofiction ?","competence":"analyser-document","situation":"Trois élèves du club d’écriture présentent chacun leur projet de livre sur l’enfance. Elles échangent avec Tom. Le tableau de la bibliothèque rappelle quelques grands textes du genre.","documents":[{"id":"oeuvres","type":"tableau","titre":"Quelques récits d’enfance","colonnes":["Auteur","Œuvre","À retenir"],"lignes":[["Rousseau","Les Confessions (1782)","Inaugure le genre moderne"],["Marcel Pagnol","La Gloire de mon père","Souvenirs d’enfance"],["Hervé Bazin","Vipère au poing","La famille est un lieu de guerre"],["Nathalie Sarraute","Enfance","Souvenirs d’enfance"]],"enteteLignes":true,"source":"D’après le cours"},{"id":"club","type":"dialogue","modele":"bulles","titre":"Au club d’écriture","participants":[{"nom":"Léa","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"},{"nom":"Inès","emoji":"🧒","cote":"gauche"}],"repliques":[{"qui":"Léa","texte":"Mon livre promet de raconter la vérité, rien que la vérité."},{"qui":"Tom","texte":"Le mien s’inspire de ma vie mais j’invente des scènes : j’assume la fiction."},{"qui":"Inès","texte":"Moi, je mélange volontairement les deux."}]}],"questions":[{"enonce":"Dans le tableau, touche le titre de l’œuvre où la famille est un lieu de guerre.","aide":"Regarde la dernière colonne.","type":"zone","document":"oeuvres","multiple":false},{"enonce":"Touche le mot de Léa qui montre qu’elle signe un pacte autobiographique.","aide":"Elle promet de dire ce qui s’est vraiment passé.","type":"zone","document":"club","multiple":true},{"enonce":"Relie chaque élève au genre de son livre.","aide":"Qui promet la vérité ? Qui assume la fiction ? Qui mêle les deux volontairement ?","type":"association","gauche":[{"id":"g0","texte":"Léa"},{"id":"g1","texte":"Tom"},{"id":"g2","texte":"Inès"}],"droite":[{"id":"d0","texte":"Roman autobiographique"},{"id":"d1","texte":"Autofiction"},{"id":"d2","texte":"Autobiographie"}]},{"enonce":"Pourquoi tout récit d’enfance est-il en partie une invention ?","aide":"Pense à la façon dont on se souvient d’une journée d’il y a dix ans.","type":"choix","options":[{"id":"a","texte":"Parce que la mémoire reconstruit au lieu d’enregistrer"},{"id":"b","texte":"Parce que les auteurs mentent pour se faire aimer"},{"id":"c","texte":"Parce que les enfants inventent tout ce qu’ils vivent"},{"id":"d","texte":"Parce que les éditeurs réécrivent les souvenirs"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"**Vipère au poing**, de Hervé Bazin, montre une famille qui est un lieu de guerre."},{"cle":{"type":"zone","ids":["m6"]},"explication":"Léa promet la **vérité** : c’est la promesse de l’autobiographie."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Léa promet la vérité (**autobiographie**), Tom s’inspire de sa vie mais assume la fiction (**roman autobiographique**), Inès mêle les deux volontairement (**autofiction**)."},{"cle":{"type":"choix","ids":["a"]},"explication":"La mémoire **reconstruit** : l’invention vient de sa nature, pas d’un mensonge."}]$ex$::jsonb),
  ('6599efec-fefb-5c60-86a9-b028fa4f86ed'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Ma tante Odile","competence":"analyser-texte","situation":"Un adulte se souvient de sa tante, vue avec ses yeux d’enfant. Un petit tableau rappelle les temps du passé. Ton travail : distinguer les deux voix et sentir ce que leur écart produit.","documents":[{"id":"odile","type":"texte","genre":"recit","titre":"Souvenir d’un dimanche","blocs":["Ma tante Odile me paraissait immense, avec ses mains de géante et une voix de tonnerre. Chaque dimanche, elle m’embrassait si fort que j’en perdais le souffle.","Un jour, en épluchant des oignons, elle éclata en sanglots. Je pensais que c’était à cause des oignons.","Aujourd’hui, je sais que son mari venait de mourir."],"source":"Texte écrit pour l’exercice"},{"id":"temps","type":"tableau","titre":"Les temps du passé","colonnes":["Temps","Emploi"],"lignes":[["Imparfait","Le décor et les habitudes"],["Passé simple","Un événement précis"]],"enteteLignes":true,"source":"D’après le cours"}],"questions":[{"enonce":"Les adultes sont « vus d’en bas » et agrandis. Touche les **deux expressions** qui agrandissent la tante.","aide":"Cherche ce qui la fait ressembler à une géante ou à un orage.","type":"zone","document":"odile","multiple":true},{"enonce":"Touche le verbe au passé simple qui marque l’événement du souvenir.","aide":"D’après le tableau, ce temps sert à un événement précis.","type":"zone","document":"odile","multiple":true},{"enonce":"Classe ces phrases selon la voix qui parle.","aide":"L’enfant ne sait pas ; l’adulte sait et commente.","type":"categories","categories":[{"id":"c0","texte":"Je narré (l’enfant)"},{"id":"c1","texte":"Je narrant (l’adulte)"}],"items":[{"id":"i0","texte":"Je comprends maintenant son chagrin"},{"id":"i1","texte":"Je pensais que c’était à cause des oignons"},{"id":"i2","texte":"Elle me paraissait immense"},{"id":"i3","texte":"Aujourd’hui, je sais que son mari venait de mourir"}]},{"enonce":"Que produit l’écart entre l’enfant qui ne savait pas et l’adulte qui sait ?","aide":"L’adulte regarde l’enfant qu’il était, en sachant pourquoi la tante pleurait.","type":"choix","options":[{"id":"a","texte":"Une démonstration mathématique"},{"id":"b","texte":"Une description scientifique"},{"id":"c","texte":"De la tendresse ou du regret"},{"id":"d","texte":"Un portrait neutre et sans émotion"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m8","m9","m10","m12","m13","m14","m15"]},"explication":"**ses mains de géante** et **une voix de tonnerre** agrandissent la tante par le regard de l’enfant."},{"cle":{"type":"zone","ids":["m36"]},"explication":"**éclata** est au passé simple : il marque l’événement (les sanglots), alors que les autres verbes décrivent l’habitude."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Le **je narré** voit comme l’enfant ; le **je narrant** comprend après coup."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’écart entre les deux voix crée de la **tendresse**, de l’ironie ou du regret."}]$ex$::jsonb),
  ('3a7a28dd-117c-5eac-9606-4dc594d578b4'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Alix et la baguette d’argent","competence":"analyser-texte","situation":"Pour le concours de contes de la bibliothèque, Alix lit un conte inventé. Avant de voter, le jury repère les marques qui font de ce texte un conte merveilleux.","documents":[{"id":"alix","type":"texte","genre":"recit","titre":"La baguette d’argent","blocs":["Il était une fois une jeune fille nommée Alix, qui vivait avec sa marâtre.","Un soir, une fée lui offrit une baguette d’argent et lui dit : « Tu devras passer trois épreuves. »","Alix ne s’étonna pas du tout : dans ce pays, tout le monde croisait des êtres magiques."],"source":"Conte écrit pour l’exercice"}],"questions":[{"enonce":"Touche la formule d’ouverture qui place l’histoire dans un temps indéterminé.","aide":"C’est la formule qui commence presque tous les contes.","type":"zone","document":"alix","multiple":true},{"enonce":"Touche les **deux personnages types** des contes.","aide":"Cherche une belle-mère cruelle et une aide magique.","type":"zone","document":"alix","multiple":true},{"enonce":"Touche l’objet magique du récit.","aide":"Les fées en donnent souvent un.","type":"zone","document":"alix","multiple":true},{"enonce":"Pourquoi ce conte est-il un conte merveilleux et non un récit fantastique ?","aide":"Relis la dernière phrase : Alix est-elle surprise ?","type":"choix","options":[{"id":"a","texte":"Il raconte un doute sur ce qui est réel"},{"id":"b","texte":"Il se termine toujours mal"},{"id":"c","texte":"Le surnaturel y est admis sans étonner personne"},{"id":"d","texte":"Il se passe dans une ville moderne"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m1","m2","m3"]},"explication":"**Il était une fois** est la formule d’ouverture du conte."},{"cle":{"type":"zone","ids":["m13","m17"]},"explication":"La **marâtre** et la **fée** sont des personnages types du conte."},{"cle":{"type":"zone","ids":["m21"]},"explication":"La **baguette** est un objet magique."},{"cle":{"type":"choix","ids":["c"]},"explication":"Dans le merveilleux, le surnaturel est **admis d’emblée** : Alix ne s’étonne pas."}]$ex$::jsonb),
  ('3a7a28dd-117c-5eac-9606-4dc594d578b4'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le dragon qui but le lac","competence":"analyser-texte","situation":"Léa raconte à la classe un conte de sa fabrication. Le professeur lui demande de retrouver les cinq étapes du schéma narratif et les rôles du schéma actanciel.","documents":[{"id":"lac","type":"texte","genre":"recit","titre":"Le dragon qui but le lac","blocs":["Au royaume de Valmer, tout le monde vivait heureux au bord du lac.","Un matin, un dragon but toute l’eau du lac. Le roi, désespéré, envoya le jeune Noé chercher l’eau perdue.","Noé traversa une forêt de ronces, puis une montagne de glace. Une cigogne devint son amie et lui montra le chemin.","Noé endormit le dragon avec une chanson et le lac se remplit de nouveau.","Depuis ce jour, le royaume vit en paix."],"source":"Conte écrit pour l’exercice"}],"questions":[{"enonce":"Range les cinq étapes du schéma narratif dans l’ordre.","aide":"L’équilibre vient d’abord, puis il est rompu, puis le héros lutte.","type":"ordre","items":[{"id":"a","texte":"Élément de résolution"},{"id":"b","texte":"Élément perturbateur"},{"id":"c","texte":"Situation finale"},{"id":"d","texte":"Péripéties"},{"id":"e","texte":"Situation initiale"}]},{"enonce":"Touche l’élément perturbateur : ce qui rompt l’équilibre du début.","aide":"Que se passe-t-il « un matin » ?","type":"zone","document":"lac","multiple":true},{"enonce":"Touche l’élément de résolution : ce qui dénoue l’histoire.","aide":"Cherche ce que fait Noé pour arrêter le dragon.","type":"zone","document":"lac","multiple":true},{"enonce":"Dans le schéma actanciel, touche l’adjuvant : celui qui aide le héros.","aide":"C’est un animal qui montre le chemin.","type":"zone","document":"lac","multiple":true},{"enonce":"Relie chaque personnage à son rôle dans le schéma actanciel.","aide":"Le sujet poursuit un objet ; le destinateur envoie ; l’adjuvant aide ; l’opposant gêne.","type":"association","gauche":[{"id":"g0","texte":"Noé"},{"id":"g1","texte":"Le roi"},{"id":"g2","texte":"La cigogne"},{"id":"g3","texte":"Le dragon"}],"droite":[{"id":"d0","texte":"Destinateur"},{"id":"d1","texte":"Sujet"},{"id":"d2","texte":"Opposant"},{"id":"d3","texte":"Adjuvant"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"ordre","ids":["e","b","d","a","c"]},"explication":"Dans l’ordre : **situation initiale**, **élément perturbateur**, **péripéties**, **élément de résolution**, **situation finale**."},{"cle":{"type":"zone","ids":["m15","m16","m17","m18","m19","m20","m21","m22"]},"explication":"**un dragon but toute l’eau du lac** : le bonheur du royaume est rompu."},{"cle":{"type":"zone","ids":["m55","m56","m57","m58","m59","m60","m61"]},"explication":"**Noé endormit le dragon avec une chanson** : c’est ce qui dénoue l’histoire."},{"cle":{"type":"zone","ids":["m46"]},"explication":"La **cigogne** aide Noé : c’est l’adjuvant."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g3":"d2","g2":"d3"}},"explication":"Noé est le **sujet** (il part en quête), le roi est le **destinateur** (il l’envoie), la cigogne est l’**adjuvant**, le dragon est l’**opposant**."}]$ex$::jsonb),
  ('3a7a28dd-117c-5eac-9606-4dc594d578b4'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une voix dans le couloir","competence":"comprendre-langue","situation":"Pour le défi « deux genres, un seul surnaturel », Mina et un narrateur de ton âge vivent chacun une histoire étrange. Il faut déterminer lequel est un merveilleux et lequel un fantastique.","documents":[{"id":"texteA","type":"texte","genre":"recit","titre":"Texte A : la reine des abeilles","blocs":["La reine des abeilles salua Mina : « Bonjour, petite. Où vas-tu ? » Mina ne s’étonna pas et lui offrit du miel."],"source":"Texte écrit pour l’exercice"},{"id":"texteB","type":"texte","genre":"recit","titre":"Texte B : le couloir","blocs":["Ce soir-là, dans le couloir de l’immeuble, la porte de l’ascenseur s’ouvrit sans personne. Une voix murmura mon prénom. Je crus rêver, ou avoir confondu avec la télévision… Je n’étais plus sûr de rien."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Le texte A est :","aide":"Mina est-elle surprise qu’une reine des abeilles parle ?","type":"choix","options":[{"id":"a","texte":"Un récit de voyage"},{"id":"b","texte":"Un récit fantastique"},{"id":"c","texte":"Une autobiographie"},{"id":"d","texte":"Un conte merveilleux"}],"multiple":false},{"enonce":"Touche les mots qui montrent que le surnaturel est accepté sans surprise.","aide":"Cherche la réaction de Mina.","type":"zone","document":"texteA","multiple":true},{"enonce":"Touche les **deux expressions** qui montrent le doute du narrateur.","aide":"Il hésite entre le rêve et la réalité.","type":"zone","document":"texteB","multiple":true},{"enonce":"Classe ces phrases selon le genre.","aide":"Demande-toi : le héros doute-t-il ou accepte-t-il ?","type":"categories","categories":[{"id":"c0","texte":"Merveilleux"},{"id":"c1","texte":"Fantastique"}],"items":[{"id":"i0","texte":"Le narrateur hésite entre rêve et réalité"},{"id":"i1","texte":"Une voix inexplicable murmure un prénom dans le couloir (texte B)"},{"id":"i2","texte":"La reine des abeilles parle à Mina (texte A)"},{"id":"i3","texte":"Mina offre du miel sans être surprise"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"Le surnaturel est admis d’emblée : c’est du **merveilleux**."},{"cle":{"type":"zone","ids":["m11","m12","m13","m14"]},"explication":"**ne s’étonna pas** : le surnaturel est admis, c’est la marque du merveilleux."},{"cle":{"type":"zone","ids":["m22","m23","m24","m31","m32","m33","m34","m35","m36","m37"]},"explication":"**Je crus rêver** et **Je n’étais plus sûr de rien** disent le doute : c’est la marque du fantastique."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Dans le **merveilleux**, le surnaturel est accepté ; dans le **fantastique**, il surgit dans un monde réaliste et provoque le **doute**."}]$ex$::jsonb),
  ('c841f7b9-62c1-579c-9266-06e8246818e5'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"L’île que nulle carte ne montre","competence":"analyser-texte","situation":"Un navigateur imaginaire aborde une île étrange et note ce qu’il y voit. Dans la classe, on repère les marques d’une utopie.","documents":[{"id":"ile","type":"texte","genre":"recit","titre":"Récit d’un voyageur","blocs":["Le navigateur Hugo aborda une île perdue au milieu de l’océan, que nulle carte ne montrait.","Ici, personne n’est plus riche qu’un autre et tout le monde travaille six heures par jour. Les enfants vont tous à l’école, et les lois tiennent sur une seule page."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui désigne le lieu isolé où se passe l’utopie.","aide":"C’est un lieu entouré d’eau.","type":"zone","document":"ile","multiple":true},{"enonce":"Touche les **quatre traits** de cette société : égalité, travail partagé, éducation, lois simples.","aide":"Cherche ce qui concerne la richesse, le temps de travail, l’école et les lois.","type":"zone","document":"ile","multiple":true},{"enonce":"Touche les mots qui disent que cette île n’existe sur aucune carte.","aide":"La première phrase le dit.","type":"zone","document":"ile","multiple":true},{"enonce":"Que signifie le mot « utopie », inventé par Thomas More ?","aide":"Le mot vient du grec *ou-topos*.","type":"choix","options":[{"id":"a","texte":"« En aucun lieu »"},{"id":"b","texte":"« Pays du bonheur »"},{"id":"c","texte":"« Île du trésor »"},{"id":"d","texte":"« Voyage lointain »"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5"]},"explication":"Une **île** est un lieu isolé : le cadre habituel d’une utopie."},{"cle":{"type":"zone","ids":["m18","m19","m20","m21","m22","m23","m24","m25","m30","m31","m32","m33","m34","m35","m36","m37","m38","m39","m40","m41","m43","m44","m45","m46","m47","m48","m49"]},"explication":"Ce sont **l’égalité**, le **travail partagé et limité**, l’**éducation pour tous** et les **lois simples**."},{"cle":{"type":"zone","ids":["m12","m13","m14","m15","m16"]},"explication":"**que nulle carte ne montrait** : l’île n’existe nulle part, c’est le sens du mot « utopie »."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Utopie** vient du grec *ou-topos* : « en aucun lieu »."}]$ex$::jsonb),
  ('c841f7b9-62c1-579c-9266-06e8246818e5'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Ici, pas là-bas","competence":"argumenter","situation":"Thomas More a imaginé une île parfaite pour critiquer son propre pays. Un tableau et une courte fiche sur Thélème t’aident à comprendre cette critique indirecte.","documents":[{"id":"more","type":"tableau","titre":"L’île de More et son pays","colonnes":["Thème","Dans l’île d’*Utopie*","Dans l’Angleterre de More"],"lignes":[["Richesse","Égalité entre les habitants","Enclosures et misère"],["Propriété","Commune ou fortement encadrée","Privée, avec des enclosures"]],"enteteLignes":true,"source":"D’après le cours"},{"id":"theleme","type":"texte","genre":"article","titre":"L’abbaye de Thélème","blocs":["Chez Rabelais, l’abbaye de Thélème n’a qu’une seule règle : « Fais ce que voudras »."],"source":"Fiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche dans le tableau ce que More vise vraiment en décrivant son île sans propriété privée.","aide":"Il critique son pays par contraste.","type":"zone","document":"more","multiple":false},{"enonce":"Pourquoi dit-on que l’argumentation de More est « indirecte » ?","aide":"Il ne dit pas « mon pays est injuste » : que montre-t-il à la place ?","type":"choix","options":[{"id":"a","texte":"Il critique son pays en montrant un monde parfait ailleurs"},{"id":"b","texte":"Il écrit une lettre directe au roi pour se plaindre"},{"id":"c","texte":"Il ne critique rien et raconte seulement un rêve"},{"id":"d","texte":"Il décrit exactement une île qu’il a visitée"}],"multiple":false},{"enonce":"Touche la règle unique de l’abbaye de Thélème.","aide":"Elle tient en trois mots, entre guillemets.","type":"zone","document":"theleme","multiple":true},{"enonce":"Relie chaque trait d’utopie à son sens.","aide":"Pense à ce que chaque trait décrit : le lieu, le droit, l’école, les biens.","type":"association","gauche":[{"id":"g0","texte":"Lieu isolé"},{"id":"g1","texte":"Lois simples"},{"id":"g2","texte":"Éducation"},{"id":"g3","texte":"Propriété"}],"droite":[{"id":"d0","texte":"Commune ou fortement encadrée"},{"id":"d1","texte":"Peu de crimes, peu de juges"},{"id":"d2","texte":"Une île, une vallée, une planète"},{"id":"d3","texte":"Offerte à tous les habitants"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"More vise **l’Angleterre de son temps**, ses **enclosures et sa misère**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Il montre ce qui **pourrait être** pour faire voir ce qui ne va pas : c’est une argumentation **indirecte**."},{"cle":{"type":"zone","ids":["m12","m13","m14","m15"]},"explication":"La règle de Thélème est **Fais ce que voudras**."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"Chaque trait participe à la société idéale décrite par les utopies."}]$ex$::jsonb),
  ('c841f7b9-62c1-579c-9266-06e8246818e5'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Bienvenue à Lumeria","competence":"argumenter","situation":"Une cité « parfaite », Lumeria, vante son bonheur. Un schéma montre comment l’utopie peut basculer. Ton travail : repérer ce qui ressemble à une utopie… et ce qui la fait basculer.","documents":[{"id":"lumeria","type":"texte","genre":"article","titre":"Brochure de Lumeria","blocs":["Bienvenue à Lumeria, la cité parfaite. Ici, toutes les maisons sont identiques et une cloche règle les horaires : on se lève, on travaille et on mange en même temps. Personne n’a faim, personne ne se dispute.","Mais des yeux de verre surveillent chaque rue, et ceux qui refusent ce bonheur sont priés de « se reposer » dans une maison à part."],"source":"Brochure imaginée pour l’exercice"},{"id":"basculement","type":"chaine","titre":"Du rêve au cauchemar","disposition":"ligne","noeuds":[{"id":"z1","texte":"Une société parfaite"},{"id":"z2","texte":"L’uniformité nécessaire"},{"id":"z3","texte":"La surveillance"},{"id":"z4","texte":"?"}],"liens":[{"de":"z1","a":"z2","texte":"suppose"},{"de":"z2","a":"z3","texte":"entraîne"},{"de":"z3","a":"z4","texte":"mène à"}]}],"questions":[{"enonce":"Touche les **deux traits** qui montrent une organisation rationnelle de la cité.","aide":"Cherche ce qui est identique et réglé comme une horloge.","type":"zone","document":"lumeria","multiple":true},{"enonce":"Touche ce qui fait basculer la cité vers la dystopie.","aide":"Cherche ce qui contrôle chaque habitant.","type":"zone","document":"lumeria","multiple":true},{"enonce":"Touche les personnes que la cité écarte parce qu’elles ne veulent pas du même bonheur que les autres.","aide":"Ils refusent le bonheur imposé.","type":"zone","document":"lumeria","multiple":true},{"enonce":"Que faut-il écrire à la place du « ? » dans le schéma ?","aide":"L’utopie, quand elle devient oppressante, change de nom.","type":"choix","options":[{"id":"a","texte":"La dystopie"},{"id":"b","texte":"Le voyage"},{"id":"c","texte":"L’égalité parfaite"},{"id":"d","texte":"La liberté"}],"multiple":false},{"enonce":"Quelle question toute utopie contient-elle ?","aide":"Pense à ceux qui ne sont pas d’accord avec la cité parfaite.","type":"choix","options":[{"id":"a","texte":"Combien de temps dure le voyage ?"},{"id":"b","texte":"Qui décide de ce qui est parfait ?"},{"id":"c","texte":"Qui a inventé le mot « utopie » ?"},{"id":"d","texte":"Où se trouve l’île du trésor ?"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m8","m9","m10","m11","m13","m14","m15","m16","m17"]},"explication":"**toutes les maisons sont identiques** et **une cloche règle les horaires** : villes identiques et horaires réglés sont des traits d’utopie."},{"cle":{"type":"zone","ids":["m38","m39","m40","m41","m42","m43","m44"]},"explication":"**des yeux de verre surveillent chaque rue** : la surveillance fait basculer l’utopie vers la dystopie."},{"cle":{"type":"zone","ids":["m46","m47","m48","m49","m50"]},"explication":"**ceux qui refusent ce bonheur** sont écartés : une société parfaite suppose que tout le monde veuille la même chose."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’utopie, par l’uniformité et la surveillance, mène à la **dystopie**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Toute utopie contient sa propre inquiétude : **qui décide de ce qui est parfait**, et que fait-on de ceux qui ne sont pas d’accord ?"}]$ex$::jsonb),
  ('6b657546-53d8-51cd-8eaf-0b914516971f'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le Citoyen 417","competence":"analyser-texte","situation":"Le club de lecture étudie le début d’un roman imaginaire qui se passe dans une ville où tout est contrôlé. Il faut repérer les traits d’une dystopie.","documents":[{"id":"citoyen","type":"texte","genre":"recit","titre":"Le début du roman","blocs":["Le haut-parleur grésille : « Le Régime vous aime. Le Régime vous protège. »","Le Citoyen 417 baisse la tête. Dans cette ville, personne n’a plus de prénom : chacun est désigné par un numéro.","Sur le mur, un grand œil peint suit chaque passant.","Hier, 417 a ouvert un livre interdit. Aujourd’hui, une caméra le suit jusqu’à son immeuble."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui montrent que les habitants sont désignés par des numéros.","aide":"Cherche un chiffre et un mot qui remplace le prénom.","type":"zone","document":"citoyen","multiple":true},{"enonce":"Touche la phrase de **propagande** diffusée par le haut-parleur.","aide":"C’est un slogan répété pour que les habitants aiment le régime.","type":"zone","document":"citoyen","multiple":true},{"enonce":"Touche les **deux éléments** qui montrent la surveillance permanente.","aide":"Un grand dessin sur un mur, et un appareil qui suit quelqu’un.","type":"zone","document":"citoyen","multiple":true},{"enonce":"Qu’est-ce qu’une dystopie ?","aide":"C’est l’inverse d’une utopie.","type":"choix","options":[{"id":"a","texte":"Une île imaginaire où tout le monde est parfaitement heureux"},{"id":"b","texte":"Un conte où les animaux parlent et les fées existent"},{"id":"c","texte":"Une société parfaite en apparence, totalitaire en réalité"},{"id":"d","texte":"Un long voyage vers un pays lointain et mystérieux"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13","m31"]},"explication":"**417** et **numéro** : dans une dystopie, les individus sont souvent désignés par des numéros."},{"cle":{"type":"zone","ids":["m3","m4","m5","m6","m7","m8","m9","m10"]},"explication":"**Le Régime vous aime. Le Régime vous protège.** est de la propagande."},{"cle":{"type":"zone","ids":["m37","m38","m50","m51","m52","m53"]},"explication":"Un **œil peint** et **une caméra** montrent la surveillance permanente."},{"cle":{"type":"choix","ids":["c"]},"explication":"Une dystopie décrit une société **en apparence parfaite, en réalité totalitaire**."}]$ex$::jsonb),
  ('6b657546-53d8-51cd-8eaf-0b914516971f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Obéir par peur ou par plaisir","competence":"analyser-document","situation":"Pour son exposé sur la dystopie, Samir a rassemblé un tableau d’œuvres et rédigé une petite note sur deux formes d’oppression. Son travail : relier les œuvres aux idées.","documents":[{"id":"oeuvres","type":"tableau","titre":"Quatre grandes dystopies","colonnes":["Auteur","Œuvre","Date","Ressort"],"lignes":[["Evgueni Zamiatine","Nous autres","1920","Le premier du genre"],["Aldous Huxley","Le Meilleur des mondes","1932","Heureux par conditionnement et par drogue"],["George Orwell","1984","1949","Big Brother et la novlangue"],["Ray Bradbury","Fahrenheit 451","1953","Des pompiers qui brûlent les livres"]],"enteteLignes":true,"source":"D’après le cours"},{"id":"note","type":"texte","genre":"article","titre":"Deux formes d’oppression","blocs":["Dans le roman A, les habitants obéissent par peur : la surveillance et la torture les tiennent. Dans le roman B, ils obéissent par plaisir : le divertissement et le confort les endorment."],"source":"Note imaginée pour l’exercice"}],"questions":[{"enonce":"Combien d’années séparent *Nous autres* de *1984* ?","aide":"Regarde la colonne « Date » pour les deux œuvres.","type":"nombre","unite":"ans"},{"enonce":"Touche la date de publication de l’œuvre où des pompiers brûlent les livres.","aide":"Repère d’abord la ligne des pompiers, puis la colonne « Date ».","type":"zone","document":"oeuvres","multiple":false},{"enonce":"Touche le mot qui dit pourquoi les habitants obéissent dans le roman B.","aide":"C’est une obéissance sans contrainte apparente.","type":"zone","document":"note","multiple":true},{"enonce":"Relie chaque œuvre à la façon d’obtenir l’obéissance.","aide":"Orwell : surveillance et torture ; Huxley : conditionnement et drogue ; Bradbury : les pompiers.","type":"association","gauche":[{"id":"g0","texte":"1984"},{"id":"g1","texte":"Le Meilleur des mondes"},{"id":"g2","texte":"Fahrenheit 451"}],"droite":[{"id":"d0","texte":"La destruction des livres"},{"id":"d1","texte":"Le plaisir"},{"id":"d2","texte":"La peur"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":29,"tolerance":0},"affichage":"29 ans","explication":"De 1920 à 1949, il y a 1949 − 1920 = **29 ans**."},{"cle":{"type":"zone","ids":["r3c2"]},"explication":"Les pompiers de **Fahrenheit 451** sont publiés en **1953**."},{"cle":{"type":"zone","ids":["m23"]},"explication":"Dans le roman B, on obéit par **plaisir** : le divertissement et le confort remplacent la contrainte."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"Chez **Orwell** on obéit par **peur**, chez **Huxley** par **plaisir**, et chez **Bradbury** les pompiers brûlent les livres."}]$ex$::jsonb),
  ('6b657546-53d8-51cd-8eaf-0b914516971f'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le dictionnaire du Régime","competence":"argumenter","situation":"Dans une ville imaginaire, le Régime publie une nouvelle édition de son dictionnaire. Une habitante en parle à une amie. Tu dois comprendre comment on peut rendre la révolte impensable.","documents":[{"id":"dico","type":"fiche","modele":"panneau","entete":"Le Dictionnaire du Régime","sousTitre":"Édition réduite","emoji":"📖","teinte":"gris","lignes":[{"texte":"Liberté","valeur":"supprimé","id":"z1"},{"texte":"Révolte","valeur":"supprimé","id":"z2"},{"texte":"Bon","valeur":"gardé","id":"z3"},{"texte":"Très bon","valeur":"plusbon","id":"z4"},{"texte":"Mauvais","valeur":"inbon","id":"z5"}],"pied":"Moins de mots, moins de soucis."},{"id":"amies","type":"dialogue","modele":"bulles","titre":"Dans la rue","participants":[{"nom":"Lena","emoji":"👩","cote":"gauche"},{"nom":"Mara","emoji":"🧑","cote":"droite"}],"repliques":[{"qui":"Lena","texte":"Je voudrais dire que ce régime est injuste, mais ce mot n’existe plus."},{"qui":"Mara","texte":"Moi, je n’arrive même plus à y penser."}]}],"questions":[{"enonce":"Touche les **deux mots supprimés** qui rendent la contestation impossible.","aide":"Cherche les mots marqués « supprimé ».","type":"zone","document":"dico","multiple":true},{"enonce":"Touche les mots de Lena qui montrent l’effet de ce dictionnaire.","aide":"Elle ne trouve plus le mot dont elle a besoin.","type":"zone","document":"amies","multiple":true},{"enonce":"Pourquoi le Régime réduit-il le vocabulaire ?","aide":"Que devient une idée quand on n’a plus de mot pour la dire ?","type":"choix","options":[{"id":"a","texte":"Pour économiser le papier des livres"},{"id":"b","texte":"Pour que les habitants parlent plus vite"},{"id":"c","texte":"Pour rendre la révolte littéralement impensable"},{"id":"d","texte":"Pour faciliter l’apprentissage de la lecture"}],"multiple":false},{"enonce":"Que fait l’auteur d’une dystopie en inventant une telle langue ?","aide":"La dystopie ne prédit pas : elle prend une tendance de son époque.","type":"choix","options":[{"id":"a","texte":"Il pousse à l’extrême le contrôle des mots"},{"id":"b","texte":"Il prédit exactement le dictionnaire de demain"},{"id":"c","texte":"Il fait le portrait d’un pays réel qu’il a visité"},{"id":"d","texte":"Il raconte un conte sans lien avec notre monde"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2"]},"explication":"**Liberté** et **révolte** sont supprimés : sans ces mots, on ne peut plus les penser."},{"cle":{"type":"zone","ids":["m9","m10","m11","m12","m13"]},"explication":"**ce mot n’existe plus** : la langue appauvrie rend la révolte **impensable**."},{"cle":{"type":"choix","ids":["c"]},"explication":"La **novlangue** est une langue appauvrie qui rend la révolte **impensable**."},{"cle":{"type":"choix","ids":["a"]},"explication":"La dystopie prend une **tendance de son époque** (ici la propagande) et la **pousse à l’extrême** pour la rendre visible."}]$ex$::jsonb),
  ('a4a0a655-c66d-5180-9dba-7afc5b3d5891'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Aymeri, chevalier exemplaire","competence":"analyser-texte","situation":"Le conteur du château présente un chevalier imaginaire. À toi de reconnaître les valeurs d’un vrai chevalier.","documents":[{"id":"aymeri","type":"texte","genre":"recit","titre":"La journée d’Aymeri","blocs":["Le chevalier Aymeri terrasse trois brigands à lui seul. Il a juré fidélité à son seigneur : il ne le trahira jamais.","En rentrant, il partage son pain avec un vagabond affamé et salue la dame du château avec élégance."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le geste qui montre la **largesse** du chevalier, c’est-à-dire sa générosité envers les pauvres.","aide":"Cherche ce qu’il offre à quelqu’un qui a faim.","type":"zone","document":"aymeri","multiple":true},{"enonce":"Relie chaque valeur au geste d’Aymeri.","aide":"Pense : combat, fidélité, générosité, manières.","type":"association","gauche":[{"id":"g0","texte":"La prouesse"},{"id":"g1","texte":"La loyauté"},{"id":"g2","texte":"La largesse"},{"id":"g3","texte":"La courtoisie"}],"droite":[{"id":"d0","texte":"Il terrasse trois brigands"},{"id":"d1","texte":"Il partage son pain"},{"id":"d2","texte":"Il salue la dame avec élégance"},{"id":"d3","texte":"Il reste fidèle à son seigneur"}]},{"enonce":"Quel défaut le chevalier doit-il éviter, selon le cours ?","aide":"Roland en meurt, à Roncevaux.","type":"choix","options":[{"id":"a","texte":"La générosité"},{"id":"b","texte":"La démesure"},{"id":"c","texte":"La fidélité"},{"id":"d","texte":"La courtoisie"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m23","m24","m25","m26","m27","m28","m29","m30"]},"explication":"**il partage son pain avec un vagabond affamé** : c’est la largesse."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"La **prouesse** est le courage au combat, la **loyauté** la fidélité, la **largesse** la générosité, la **courtoisie** le respect des dames."},{"cle":{"type":"choix","ids":["b"]},"explication":"La **démesure** est le défaut à éviter : Roland refuse par orgueil de sonner l’olifant."}]$ex$::jsonb),
  ('a4a0a655-c66d-5180-9dba-7afc5b3d5891'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Roland refuse d’appeler à l’aide","competence":"analyser-document","situation":"Dans la classe, un récit adapté de *La Chanson de Roland* est lu à voix haute. Un tableau compare les deux grandes familles de récits du Moyen Âge.","documents":[{"id":"roland","type":"texte","genre":"recit","titre":"Roncevaux, d’après La Chanson de Roland","blocs":["L’arrière-garde de Charlemagne est attaquée à Roncevaux. Son ami Olivier supplie Roland de sonner l’olifant pour appeler l’armée.","Roland refuse par orgueil. Quand il sonne enfin son cor, il est trop tard : ses hommes sont presque tous morts.","Il meurt le visage tourné vers l’ennemi. Charlemagne viendra venger les siens."],"source":"Récit adapté pour l’exercice, d’après La Chanson de Roland (vers 1100)"},{"id":"genres","type":"tableau","titre":"Deux familles de récits","colonnes":["","Chanson de geste","Roman de chevalerie"],"lignes":[["Époque","XIe-XIIe siècles","XIIe-XIIIe siècles"],["Ce qu’il célèbre","Exploits guerriers, fidélité au seigneur","L’amour et la quête intérieure"],["Forme","En vers, chanté par les jongleurs","Écrit pour être lu"],["Modèle","La Chanson de Roland","Chrétien de Troyes"]],"enteteLignes":true,"source":"D’après le cours"}],"questions":[{"enonce":"Touche les mots qui disent pourquoi Roland refuse d’appeler à l’aide.","aide":"Cherche le défaut qui le perd.","type":"zone","document":"roland","multiple":true},{"enonce":"Touche le nom de l’instrument que Roland aurait dû sonner plus tôt.","aide":"C’est un cor en ivoire.","type":"zone","document":"roland","multiple":true},{"enonce":"Touche, dans le tableau, la case qui dit comment les chansons de geste étaient diffusées.","aide":"Regarde la ligne « Forme » et la colonne « Chanson de geste ».","type":"zone","document":"genres","multiple":false},{"enonce":"À quelle famille appartient le récit de Roncevaux ?","aide":"Exploits guerriers et fidélité au seigneur : regarde le tableau.","type":"choix","options":[{"id":"a","texte":"Un conte merveilleux"},{"id":"b","texte":"Une chanson de geste"},{"id":"c","texte":"Un récit de voyage"},{"id":"d","texte":"Un roman de chevalerie"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m23","m24"]},"explication":"**par orgueil** : Roland refuse d’appeler à l’aide par démesure."},{"cle":{"type":"zone","ids":["m16"]},"explication":"L’**olifant** est le cor de Roland."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Les chansons de geste sont **en vers, chantées par les jongleurs**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Roncevaux célèbre des **exploits guerriers** et la fidélité : c’est une **chanson de geste**."}]$ex$::jsonb),
  ('a4a0a655-c66d-5180-9dba-7afc5b3d5891'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Messire Erwan et la dame inaccessible","competence":"analyser-texte","situation":"Un conteur imagine un chevalier à la manière des romans de chevalerie. Il faut y reconnaître l’amour courtois, le merveilleux et les valeurs du chevalier.","documents":[{"id":"erwan","type":"texte","genre":"recit","titre":"Messire Erwan","blocs":["Messire Erwan n’a vu la dame Aliénor qu’une fois, à la fête du château. Depuis, il accomplit des exploits pour elle, mais elle ne lui a jamais adressé un mot.","Dans la forêt, un lion le suivit comme un chien fidèle et une fée lui offrit un anneau qui rend invisible. Erwan ne s’en étonna pas. Il donna sa bourse à un mendiant.","Un jour, il voulut vaincre seul le géant, par orgueil. Il faillit y perdre la vie."],"source":"Texte écrit pour l’exercice, à la manière des romans de chevalerie"},{"id":"valeurs","type":"tableau","titre":"Les valeurs du chevalier","colonnes":["La valeur","Ce qu’elle exige"],"lignes":[["La prouesse","Le courage et la force au combat"],["La loyauté","La fidélité à son seigneur"],["La foi","Combattre pour Dieu"],["La largesse","La générosité envers les pauvres et les vaincus"],["La courtoisie","Le respect des dames, la maîtrise de soi"]],"enteteLignes":true,"source":"D’après le cours"}],"questions":[{"enonce":"Touche les mots qui montrent l’**amour courtois** : le chevalier sert une dame inaccessible.","aide":"Cherche ce qu’il fait pour la dame.","type":"zone","document":"erwan","multiple":true},{"enonce":"Que gagne le chevalier à cette souffrance amoureuse ?","aide":"Le cours dit que l’amour courtois a un effet sur le chevalier.","type":"choix","options":[{"id":"a","texte":"Elle le rend invisible"},{"id":"b","texte":"Elle lui fait perdre sa loyauté"},{"id":"c","texte":"Elle le rend meilleur"},{"id":"d","texte":"Elle lui donne un royaume"}],"multiple":false},{"enonce":"Erwan donne sa bourse à un mendiant. Touche la valeur du tableau qu’il illustre.","aide":"Il est généreux envers un pauvre.","type":"zone","document":"valeurs","multiple":false},{"enonce":"Touche le moment où Erwan commet la faute que le cours appelle la **démesure**.","aide":"Il veut tout faire seul, par orgueil.","type":"zone","document":"erwan","multiple":true},{"enonce":"Pourquoi Erwan ne s’étonne-t-il pas de voir un lion fidèle et une fée ?","aide":"Pense au conte merveilleux : le surnaturel est-il une surprise ?","type":"choix","options":[{"id":"a","texte":"Le merveilleux fait partie de son monde"},{"id":"b","texte":"Il sait que la dame lui a tendu un piège"},{"id":"c","texte":"Il pense rêver et attend de se réveiller"},{"id":"d","texte":"Il a déjà rencontré ces êtres plusieurs fois"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17","m18","m19","m20","m21","m22"]},"explication":"**il accomplit des exploits pour elle** : c’est l’amour courtois."},{"cle":{"type":"choix","ids":["c"]},"explication":"La souffrance amoureuse **rend le chevalier meilleur**."},{"cle":{"type":"zone","ids":["r3c0"]},"explication":"Donner sa bourse à un mendiant illustre la **largesse**."},{"cle":{"type":"zone","ids":["m68","m69","m70","m71","m72","m73"]},"explication":"**il voulut vaincre seul le géant** : c’est la démesure, le défaut à éviter."},{"cle":{"type":"choix","ids":["a"]},"explication":"Dans les romans de chevalerie, le **merveilleux** fait partie du monde sans surprendre personne, comme dans le conte."}]$ex$::jsonb),
  ('01669d26-296b-5577-bdc5-f80eaba6227d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le choix d’Achille","competence":"analyser-texte","situation":"Le professeur de lettres raconte aux élèves le choix d’un héros grec. Il écrit un petit texte au tableau, que la classe analyse.","documents":[{"id":"achille","type":"texte","genre":"recit","titre":"Achille","blocs":["Achille avait le choix entre deux vies : une vie longue mais obscure, ou une vie courte mais glorieuse. Il choisit la gloire.","Sa mère l’avait plongé dans un fleuve magique : seul son talon, qu’elle tenait, resta vulnérable."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les mots qui disent le choix d’Achille.","aide":"Il préfère la gloire à la durée.","type":"zone","document":"achille","multiple":true},{"enonce":"Touche le mot qui désigne son seul point vulnérable.","aide":"Il s’agit d’une partie du pied.","type":"zone","document":"achille","multiple":true},{"enonce":"Que montre le choix d’Achille ?","aide":"Il choisit une vie courte : pourquoi ?","type":"choix","options":[{"id":"a","texte":"Il est un dieu qui ne peut pas mourir"},{"id":"b","texte":"Il a peur de mourir et de souffrir"},{"id":"c","texte":"Il préfère une vie longue et tranquille"},{"id":"d","texte":"La gloire passe avant la durée de la vie"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13","m14","m15","m16","m17"]},"explication":"**une vie courte mais glorieuse** : Achille préfère la gloire à une longue vie obscure."},{"cle":{"type":"zone","ids":["m33"]},"explication":"Le **talon** est le seul point vulnérable d’Achille."},{"cle":{"type":"choix","ids":["d"]},"explication":"Pour Achille, la **gloire** compte plus que la durée de la vie."}]$ex$::jsonb),
  ('01669d26-296b-5577-bdc5-f80eaba6227d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le long retour d’Ulysse","competence":"se-reperer-espace","situation":"Une carte montre le retour d’Ulysse de Troie à Ithaque. Un tableau compare ce héros à Achille. Tu dois lire l’une avec l’autre.","documents":[{"id":"carte","type":"carte","titre":"Le retour d’Ulysse","fond":"mediterranee","cadrage":[17,34,29,42],"lieux":[{"id":"z1","lieu":"troie","nom":"Troie","symbole":"etoile","teinte":"corail"},{"id":"z2","lon":20.68,"lat":38.37,"nom":"Ithaque","symbole":"etoile","teinte":"violet"},{"id":"z3","lieu":"athenes","nom":"Athènes","symbole":"point"}],"traits":[{"id":"z4","points":["troie",[25.5,37],[22.5,35.9],[20,37.3],[20.68,38.37]],"style":"pointilles","teinte":"bleu","etiquette":"Retour d’Ulysse : dix ans"}],"source":"Trajet simplifié"},{"id":"modeles","type":"tableau","titre":"Deux modèles d’héroïsme","colonnes":["","Achille","Ulysse"],"lignes":[["Sa qualité","La force","La ruse"],["Ce qu’il vise","La gloire","Le retour"],["Son destin","La mort jeune","La survie"]],"enteteLignes":true,"source":"D’après le cours"}],"questions":[{"enonce":"Touche l’île où Ulysse veut revenir après la guerre de Troie.","aide":"Elle est à l’ouest de la Grèce, au bout du trajet pointillé.","type":"zone","document":"carte","multiple":false},{"enonce":"Combien d’années dure le retour d’Ulysse, d’après la carte ?","aide":"Lis l’étiquette du trajet.","type":"nombre","unite":"ans"},{"enonce":"Touche, dans le tableau, la case qui dit ce que vise Ulysse.","aide":"Regarde la ligne « Ce qu’il vise » et la colonne d’Ulysse.","type":"zone","document":"modeles","multiple":false},{"enonce":"Relie chaque monstre au héros qui l’affronte.","aide":"Pense aux douze travaux, au fil d’Ariane et à la Toison d’or.","type":"association","gauche":[{"id":"g0","texte":"Le Cyclope"},{"id":"g1","texte":"L’Hydre"},{"id":"g2","texte":"Le Minotaure"},{"id":"g3","texte":"Méduse"}],"droite":[{"id":"d0","texte":"Ulysse"},{"id":"d1","texte":"Héraclès"},{"id":"d2","texte":"Persée"},{"id":"d3","texte":