   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**Ithaque** est la patrie d’Ulysse, au terme de son retour."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 ans","explication":"L’étiquette dit **dix ans** : Ulysse met dix ans à rentrer à Ithaque."},{"cle":{"type":"zone","ids":["r1c2"]},"explication":"Ulysse vise le **retour**, alors qu’Achille vise la gloire."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"Ulysse affronte le **Cyclope**, Héraclès l’**Hydre**, Thésée le **Minotaure**, Persée **Méduse**."}]$ex$::jsonb),
  ('01669d26-296b-5577-bdc5-f80eaba6227d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Je m’appelle Personne","competence":"analyser-texte","situation":"Une scène de l’*Odyssée* est racontée pour la classe, dans une version adaptée. À côté, une chaîne rappelle ce que contient la vie d’un héros antique.","documents":[{"id":"cyclope","type":"texte","genre":"recit","titre":"Ulysse et le Cyclope","blocs":["Prisonnier du Cyclope, Ulysse comprend que la force ne servira à rien : le monstre est bien plus fort que ses compagnons.","Alors il invente un nom : « Je m’appelle Personne. » Quand le Cyclope hurle de douleur, ses voisins demandent : « Qui te fait du mal ? » — « Personne ! » répond-il. Les voisins repartent.","Mais en sortant, Ulysse ne résiste pas au plaisir de crier son vrai nom. Par orgueil, il attire sur lui la colère de Poséidon : ses malheurs dureront dix ans."],"source":"Récit adapté pour l’exercice, d’après l’Odyssée"},{"id":"heros","type":"chaine","titre":"La vie d’un héros","disposition":"colonne","noeuds":[{"id":"z1","texte":"Une naissance extraordinaire"},{"id":"z2","texte":"Un oracle"},{"id":"z3","texte":"Des épreuves imposées par les dieux"},{"id":"z4","texte":"Des monstres à vaincre"},{"id":"z5","texte":"Un défaut qui coûte cher"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Touche les **deux passages** qui montrent la ruse d’Ulysse.","aide":"Il trompe le monstre avec un faux nom.","type":"zone","document":"cyclope","multiple":true},{"enonce":"Classe ces traits selon le héros auquel ils conviennent.","aide":"Achille : force et gloire ; Ulysse : ruse et retour.","type":"categories","categories":[{"id":"c0","texte":"Achille"},{"id":"c1","texte":"Ulysse"}],"items":[{"id":"i0","texte":"Il met dix ans à rentrer chez lui"},{"id":"i1","texte":"Il choisit la gloire quitte à mourir jeune"},{"id":"i2","texte":"Il invente un faux nom pour tromper le monstre"},{"id":"i3","texte":"Il compte sur la force"}]},{"enonce":"Touche les mots qui montrent l’**hybris** d’Ulysse, c’est-à-dire sa démesure.","aide":"Cherche ce qui le pousse à crier son vrai nom.","type":"zone","document":"cyclope","multiple":true},{"enonce":"Le Cyclope est un monstre. Touche le maillon de la chaîne que cette scène illustre.","aide":"Cherche ce qui concerne les monstres.","type":"zone","document":"heros","multiple":false},{"enonce":"Que montre la fin du texte ?","aide":"Ulysse crie son vrai nom par orgueil : que se passe-t-il ensuite ?","type":"choix","options":[{"id":"a","texte":"Ulysse est un dieu invulnérable"},{"id":"b","texte":"Le héros antique est un modèle moral irréprochable"},{"id":"c","texte":"Les voisins du Cyclope sont très rusés"},{"id":"d","texte":"L’orgueil d’un héros est toujours puni par les dieux"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m22","m23","m24","m25","m44"]},"explication":"**il invente un nom** et **Personne** : Ulysse triomphe par la ruse, pas par la force."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"**Achille** choisit la force et la gloire ; **Ulysse** la ruse et le retour."},{"cle":{"type":"zone","ids":["m63","m64"]},"explication":"**Par orgueil** : l’hybris est toujours punie par les dieux."},{"cle":{"type":"zone","ids":["z4"]},"explication":"Le Cyclope est l’un des **monstres à vaincre** de la vie du héros."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le héros antique est **admirable et faillible** : l’hybris est **toujours punie**."}]$ex$::jsonb),
  ('6a380608-689d-5a2d-b67e-70358a89b0d7'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"L’usine qui respire","competence":"analyser-texte","situation":"Dans un roman du XIXe siècle, une usine ressemble à un monstre vivant. Voici un extrait écrit pour l’exercice, à la manière de ces romans industriels.","documents":[{"id":"usine","type":"texte","genre":"recit","titre":"Le matin à l’usine","blocs":["Le matin, la grande usine s’éveillait : elle respirait par ses cheminées et avalait les ouvriers par la porte.","Les hommes, petits rouages dans le vacarme, n’étaient plus que des outils."],"source":"Texte écrit pour l’exercice, à la manière de Zola"}],"questions":[{"enonce":"Touche les **trois verbes** qui donnent à l’usine un corps vivant.","aide":"Une usine « vivante » s’éveille, respire et mange.","type":"zone","document":"usine","multiple":true},{"enonce":"Touche les **deux mots** qui rabaissent les ouvriers à des choses.","aide":"Cherche ce qu’on trouve dans une machine et dans un atelier.","type":"zone","document":"usine","multiple":true},{"enonce":"Comment s’appelle le procédé qui donne à l’usine un corps et une volonté ?","aide":"On donne à une chose les gestes d’un être vivant.","type":"choix","options":[{"id":"a","texte":"La comparaison simple"},{"id":"b","texte":"La métaphore filée"},{"id":"c","texte":"La personnification"},{"id":"d","texte":"L’énumération"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m6","m8","m13"]},"explication":"**s’éveillait**, **respirait** et **avalait** donnent vie à l’usine : c’est une personnification."},{"cle":{"type":"zone","ids":["m22","m31"]},"explication":"**rouages** et **outils** font des hommes de simples pièces de la machine."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est la **personnification** : la machine devient vivante, l’ouvrier devient une chose."}]$ex$::jsonb),
  ('6a380608-689d-5a2d-b67e-70358a89b0d7'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux regards sur le progrès","competence":"analyser-document","situation":"Pour un exposé, Inès range les regards que des écrivains du XIXe siècle portent sur la machine. Elle y ajoute un court texte écrit pour l’exercice.","documents":[{"id":"regards","type":"tableau","titre":"Quatre écrivains, quatre regards","colonnes":["Auteur et œuvre","Ce qu’il montre"],"lignes":[["Jules Verne","Il fait des machines et de la science la matière de romans enthousiastes"],["Hugo","Il salue le train comme un poème"],["Zola, Germinal (1885)","Il décrit la mine comme une bête goulue qui dévore les hommes"],["Zola, La Bête humaine","Il fait de la locomotive un personnage"]],"enteteLignes":true,"source":"D’après le cours"},{"id":"mine","type":"texte","genre":"recit","titre":"À la mine","blocs":["La mine ouvrait sa gueule noire et avalait les hommes un à un. Les mineurs descendaient, silencieux comme des outils."],"source":"Texte écrit pour l’exercice, à la manière de Zola"}],"questions":[{"enonce":"Classe ces regards selon l’attitude de l’écrivain.","aide":"Le progrès promet de vaincre la distance ; la même machine épuise les corps.","type":"categories","categories":[{"id":"c0","texte":"Enthousiasme"},{"id":"c1","texte":"Inquiétude"}],"items":[{"id":"i0","texte":"Il fait de la locomotive un personnage inquiétant"},{"id":"i1","texte":"Il fait des machines la matière de romans enthousiastes"},{"id":"i2","texte":"Il salue le train comme un poème"},{"id":"i3","texte":"Il décrit la mine comme une bête qui dévore les hommes"}]},{"enonce":"Touche, dans le tableau, l’œuvre qui décrit la mine comme une bête goulue.","aide":"Cherche le mot « mine » dans la colonne de droite.","type":"zone","document":"regards","multiple":false},{"enonce":"Touche le verbe qui fait de la mine un monstre qui mange.","aide":"On avale ce que l’on mange.","type":"zone","document":"mine","multiple":true},{"enonce":"Que devient l’ouvrier dans ce texte ?","aide":"Relis comment les mineurs descendent.","type":"choix","options":[{"id":"a","texte":"Une chose, un outil"},{"id":"b","texte":"Un poète qui salue le progrès"},{"id":"c","texte":"Un héros qui domine la machine"},{"id":"d","texte":"Un voyageur qui explore la mine"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"**Verne** et **Hugo** sont enthousiastes ; **Zola** est inquiet devant la mine et la locomotive."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"**Germinal** (1885) décrit la mine comme une bête goulue qui dévore les hommes."},{"cle":{"type":"zone","ids":["m7"]},"explication":"**avalait** personnifie la mine : elle dévore les hommes."},{"cle":{"type":"choix","ids":["a"]},"explication":"La machine devient vivante et l’ouvrier devient **une chose** : c’est le renversement du roman industriel."}]$ex$::jsonb),
  ('6a380608-689d-5a2d-b67e-70358a89b0d7'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le refuge et la machine","competence":"analyser-texte","situation":"Face à l’industrie, certains écrivains se réfugient dans la nature. Voici un poème romantique inventé et un court passage sur une usine : deux regards opposés sur le monde.","documents":[{"id":"foret","type":"texte","genre":"poeme","titre":"Dans la forêt","blocs":["Quand la ville m’étouffe, je cours vers la forêt ;","Le ruisseau pleure avec moi sous les saules.","Les chênes, doux refuges pour mon âme lasse,","Me parlent de mes peines et les font plus légères."],"source":"Poème écrit pour l’exercice, à la manière des romantiques"},{"id":"cheminee","type":"texte","genre":"recit","titre":"La cheminée","blocs":["La cheminée toussait. Les ouvriers défilaient comme des rouages dans la fumée."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les mots qui font de la forêt un abri pour le poète.","aide":"Un abri protège de la ville qui étouffe.","type":"zone","document":"foret","multiple":true},{"enonce":"Touche le vers où la nature semble partager la tristesse du poète.","aide":"Le ruisseau « pleure ».","type":"zone","document":"foret","multiple":true},{"enonce":"Dans le texte sur l’usine, touche le mot qui rabaisse l’ouvrier à une pièce de machine.","aide":"Les ouvriers sont comparés à des pièces d’horlogerie.","type":"zone","document":"cheminee","multiple":true},{"enonce":"Classe ces idées selon le texte qui les porte.","aide":"Un texte parle de forêt, l’autre de cheminée.","type":"categories","categories":[{"id":"c0","texte":"La nature"},{"id":"c1","texte":"La machine"}],"items":[{"id":"i0","texte":"Un miroir des sentiments"},{"id":"i1","texte":"Des ouvriers devenus des rouages"},{"id":"i2","texte":"Une usine qui toussait comme un être vivant"},{"id":"i3","texte":"Un refuge pour l’âme"}]},{"enonce":"Quelle question ces deux textes posent-ils ensemble ?","aide":"Pense au titre du questionnement du chapitre.","type":"choix","options":[{"id":"a","texte":"Quelle est la plus belle forêt de France ?"},{"id":"b","texte":"Qui a inventé la machine à vapeur ?"},{"id":"c","texte":"L’homme est-il maître de la nature ou en fait-il partie ?"},{"id":"d","texte":"Combien d’ouvriers travaillent dans une usine ?"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m20","m21"]},"explication":"**doux refuges** : pour les romantiques, la nature est un **refuge**."},{"cle":{"type":"zone","ids":["m10","m11","m12","m13","m14"]},"explication":"**Le ruisseau pleure avec moi** : la nature est un **miroir de l’âme**."},{"cle":{"type":"zone","ids":["m8"]},"explication":"**rouages** : l’ouvrier est décrit comme une chose."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"Pour les romantiques, la nature est un **refuge** et un **miroir de l’âme** ; l’industrie fait de la machine un être vivant et de l’ouvrier une chose."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le chapitre se demande si l’homme est **maître** de la nature — ou s’il en fait **partie**."}]$ex$::jsonb),
  ('f4b8a80c-f446-52cc-b212-3153a99aa0ac'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Léna en 2087","competence":"analyser-texte","situation":"Dans un roman d’anticipation imaginaire, la jeune Léna découvre la ville du futur. Le professeur demande de repérer les procédés qui rendent ce futur crédible.","documents":[{"id":"lena","type":"texte","genre":"recit","titre":"Le début du roman","blocs":["Nous sommes en 2087. Léna descend du solibus, qui relie Paris à Dakar en vingt minutes.","Un robot-guide explique au nouvel arrivant : « Ici, les arbres sont remplacés par des tours à oxygène. »"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche la date qui ancre le récit dans le futur.","aide":"C’est une année, au début du texte.","type":"zone","document":"lena","multiple":true},{"enonce":"Touche le **néologisme** : un mot inventé pour désigner une réalité nouvelle.","aide":"Cherche le nom du véhicule.","type":"zone","document":"lena","multiple":true},{"enonce":"Touche le personnage qui explique ce monde au lecteur.","aide":"Il parle au nouvel arrivant.","type":"zone","document":"lena","multiple":true},{"enonce":"À quoi sert la date « 2087 » ?","aide":"L’auteur ne prédit pas, il situe son récit.","type":"choix","options":[{"id":"a","texte":"À ancrer le récit et à le rendre mesurable"},{"id":"b","texte":"À indiquer l’année de publication du livre"},{"id":"c","texte":"À prédire exactement l’avenir"},{"id":"d","texte":"À donner l’âge de l’héroïne"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m1","m2","m3"]},"explication":"**Nous sommes en 2087** : la date ancre le récit et le rend mesurable."},{"cle":{"type":"zone","ids":["m7"]},"explication":"**solibus** est un mot inventé pour un véhicule du futur : un néologisme."},{"cle":{"type":"zone","ids":["m17"]},"explication":"Le **robot-guide** explique le monde futur : l’auteur utilise un personnage guide."},{"cle":{"type":"choix","ids":["a"]},"explication":"La date **ancre le récit** dans le futur et le rend **mesurable** ; elle ne prétend pas prédire."}]$ex$::jsonb),
  ('f4b8a80c-f446-52cc-b212-3153a99aa0ac'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Verne ou Wells ?","competence":"analyser-document","situation":"Deux extraits imaginés dans l’esprit de deux grands fondateurs de l’anticipation : l’un technique et optimiste, l’autre social et inquiet. Un tableau rappelle leurs œuvres.","documents":[{"id":"oeuvres","type":"tableau","titre":"Deux fondateurs","colonnes":["Œuvre","Auteur","Type d’anticipation"],"lignes":[["De la Terre à la Lune","?","Technique, documentée, optimiste"],["La Guerre des mondes","?","Sociale et morale, souvent inquiète"],["Paris au XXe siècle","?","Technique, documentée, optimiste"],["L’Île du docteur Moreau","?","Sociale et morale, souvent inquiète"]],"enteteLignes":true,"source":"D’après le cours"},{"id":"extraits","type":"texte","genre":"recit","titre":"Deux extraits","blocs":["Extrait A : « Les ingénieurs calculent avec soin la vitesse du projectile, le poids du wagon et la quantité d’air nécessaire. »","Extrait B : « Un siècle plus tard, les riches vivent dans de hautes tours ensoleillées, tandis que les pauvres travaillent sous terre, sans jamais voir la lumière. »"],"source":"Extraits écrits pour l’exercice"}],"questions":[{"enonce":"Classe chaque œuvre selon son auteur.","aide":"Verne : technique, optimiste. Wells : sociale, inquiète.","type":"categories","categories":[{"id":"c0","texte":"Jules Verne"},{"id":"c1","texte":"H. G. Wells"}],"items":[{"id":"i0","texte":"La Guerre des mondes"},{"id":"i1","texte":"De la Terre à la Lune"},{"id":"i2","texte":"Paris au XXe siècle"},{"id":"i3","texte":"L’Île du docteur Moreau"}]},{"enonce":"Lequel des deux extraits est dans l’esprit de Wells ?","aide":"Wells : anticipation sociale et morale, souvent inquiète.","type":"choix","options":[{"id":"a","texte":"Ni l’un ni l’autre des deux extraits"},{"id":"b","texte":"L’extrait B, qui montre une société divisée"},{"id":"c","texte":"L’extrait A, qui calcule la vitesse avec soin"},{"id":"d","texte":"Les deux extraits dans la même mesure"}],"multiple":false},{"enonce":"Touche les **deux mots** qui montrent la division de la société dans l’extrait B.","aide":"Deux groupes opposés, l’un en haut, l’autre sous terre.","type":"zone","document":"extraits","multiple":true},{"enonce":"Complète ce que le cours dit des deux auteurs.","aide":"Verne documente les machines ; Wells s’inquiète pour les hommes.","type":"trous","segments":["Verne pratique l’anticipation ",0," et Wells l’anticipation ",1,"."],"banque":["ecologique","sociale","technique","politique"]}]}$ex$::jsonb,
