  ('f4b8a80c-f446-52cc-b212-3153a99aa0ac'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Marseille, 2121","competence":"analyser-texte","situation":"Noor a écrit un début de roman d’anticipation sur le climat. Une fiche propose quatre questions pour lire ce genre de roman. À toi de les appliquer.","documents":[{"id":"noor","type":"texte","genre":"recit","titre":"Journal de Noor","blocs":["12 juillet 2121. À Marseille, la mer est montée de deux mètres : nous vivons maintenant dans des flottoirs, des quartiers amarrés au port.","Le vieux Karim, arrivé de l’intérieur des terres, me demande pourquoi nous ne bâtissons plus au sol. Je lui montre la ville basse, sous deux mètres d’eau.","Hier, à la radio, un savant disait qu’on avait trop tardé à réduire la fumée des usines."],"source":"Texte écrit pour l’exercice"},{"id":"lecture","type":"tableau","titre":"Lire une anticipation","colonnes":["Étape","Question à se poser"],"lignes":[["1","Quelle tendance actuelle est poussée à l’extrême ?"],["2","Que redoute l’auteur ?"],["3","Qu’espère-t-il ?"],["4","Que dit ce futur du monde où il a été écrit ?"]],"enteteLignes":false,"source":"D’après le cours"}],"questions":[{"enonce":"Touche le néologisme qui désigne une réalité nouvelle.","aide":"Un mot inventé pour un quartier flottant.","type":"zone","document":"noor","multiple":true},{"enonce":"Touche la phrase qui rend le cadre futur crédible par un détail concret.","aide":"Une ville recouverte par l’eau.","type":"zone","document":"noor","multiple":true},{"enonce":"En suivant l’étape 1 du tableau, quelle tendance actuelle ce texte pousse-t-il à l’extrême ?","aide":"Relis les causes évoquées : la mer, la fumée des usines.","type":"choix","options":[{"id":"a","texte":"La surveillance des habitants"},{"id":"b","texte":"Le voyage dans l’espace"},{"id":"c","texte":"Le divertissement de masse"},{"id":"d","texte":"La pollution et la montée des mers"}],"multiple":false},{"enonce":"Relie chaque procédé d’écriture à son rôle.","aide":"Pense à ce que chaque procédé apporte au lecteur.","type":"association","gauche":[{"id":"g0","texte":"Une date"},{"id":"g1","texte":"Un néologisme"},{"id":"g2","texte":"Un personnage guide"},{"id":"g3","texte":"Un détail concret"}],"droite":[{"id":"d0","texte":"Il explique le monde futur au lecteur"},{"id":"d1","texte":"Elle ancre le récit et le rend mesurable"},{"id":"d2","texte":"Il rend le cadre futur crédible"},{"id":"d3","texte":"Il désigne une réalité nouvelle"}]}]}$ex$::jsonb,
