  ('720b0dcc-d36b-5605-8a79-d187aef534b0'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le jardin du moine Gaël","competence":"analyser-texte","situation":"Au Moyen Âge, un moine soigne le jardin de son couvent. Un petit récit inventé décrit le jardin et ce qui l’entoure.","documents":[{"id":"gael","type":"texte","genre":"recit","titre":"Le jardin du couvent","blocs":["Le moine Gaël soigne un jardin entouré de hauts murs. Il y cultive des herbes et des légumes pour la soupe du couvent.","Au-delà du mur commence la forêt : on dit qu’elle cache des loups, des ermites et des fées."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les mots qui disent que le jardin est « clos ».","aide":"Cherche ce qui l’entoure.","type":"zone","document":"gael","multiple":true},{"enonce":"Touche les mots qui disent à quoi sert le jardin.","aide":"Il fournit de la nourriture.","type":"zone","document":"gael","multiple":true},{"enonce":"Touche le lieu du danger et du merveilleux.","aide":"C’est ce qui commence au-delà du mur.","type":"zone","document":"gael","multiple":true},{"enonce":"Pourquoi les enluminures médiévales peignent-elles la nature sans profondeur ?","aide":"Le cours précise que ce n’est pas de la maladresse.","type":"choix","options":[{"id":"a","texte":"Parce qu’ils manquaient de couleurs"},{"id":"b","texte":"Parce qu’ils n’aimaient pas les arbres"},{"id":"c","texte":"Parce que les peintres étaient maladroits"},{"id":"d","texte":"C’est un signe voulu, pas une maladresse"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m7","m8","m9"]},"explication":"**entouré de hauts murs** : c’est un *hortus conclusus*, un jardin clos."},{"cle":{"type":"zone","ids":["m14","m15","m16","m17"]},"explication":"**herbes et légumes** : le jardin médiéval est protégé et **utile**."},{"cle":{"type":"zone","ids":["m28"]},"explication":"La **forêt** est le lieu du danger, de l’épreuve et du merveilleux."},{"cle":{"type":"choix","ids":["d"]},"explication":"Dans les enluminures, la nature est un **signe**, pas un paysage : c’est une **intention**."}]$ex$::jsonb),
  ('720b0dcc-d36b-5605-8a79-d187aef534b0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Du jardin clos à Versailles","competence":"se-reperer-temps","situation":"Une frise range les grandes époques des jardins. À côté, une brochure imaginée décrit le jardin d’un grand château. Tu dois reconnaître l’époque et le pouvoir qu’il met en scène.","documents":[{"id":"frise","type":"frise","titre":"Quatre époques de jardins","debut":1200,"fin":1800,"pas":100,"periodes":[{"id":"z1","debut":1200,"fin":1500,"nom":"Moyen Âge","teinte":"ambre"},{"id":"z2","debut":1500,"fin":1600,"nom":"Renaissance","teinte":"vert"},{"id":"z3","debut":1600,"fin":1700,"nom":"XVIIe siècle","teinte":"bleu"},{"id":"z4","debut":1700,"fin":1800,"nom":"XVIIIe siècle","teinte":"rose"}],"evenements":[]},{"id":"brochure","type":"texte","genre":"article","titre":"La visite du château","blocs":["Dans ce jardin, tout est tracé au cordeau : un axe de symétrie part du château, les parterres géométriques se répondent, les arbres taillés dessinent des formes. On dit que le roi, qui gouverne le royaume, gouverne aussi la nature."],"source":"Brochure imaginée pour l’exercice"}],"questions":[{"enonce":"Le Nôtre dessine le jardin de Versailles. Touche sa période sur la frise.","aide":"C’est le siècle de Louis XIV.","type":"zone","document":"frise","multiple":false},{"enonce":"Touche les **trois signes** de la maîtrise de l’homme sur la nature.","aide":"Un axe, des parterres, des arbres : cherche ce qui est tracé et taillé.","type":"zone","document":"brochure","multiple":true},{"enonce":"Que démontre un tel jardin ?","aide":"Ce que le roi fait aux arbres, il le fait au royaume.","type":"choix","options":[{"id":"a","texte":"La peur du roi devant la forêt"},{"id":"b","texte":"Le désir de laisser pousser librement les plantes"},{"id":"c","texte":"Le goût du roi pour la nature sauvage"},{"id":"d","texte":"La maîtrise et le pouvoir du roi"}],"multiple":false},{"enonce":"Relie chaque époque à la façon dont elle traite la nature.","aide":"Jardin clos, observation, Versailles, jardin à l’anglaise.","type":"association","gauche":[{"id":"g0","texte":"Moyen Âge"},{"id":"g1","texte":"Renaissance"},{"id":"g2","texte":"XVIIe siècle"},{"id":"g3","texte":"XVIIIe siècle"}],"droite":[{"id":"d0","texte":"Rêvée"},{"id":"d1","texte":"Encadrée"},{"id":"d2","texte":"Observée"},{"id":"d3","texte":"Soumise"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Versailles est dessiné au **XVIIe siècle**."},{"cle":{"type":"zone","ids":["m9","m10","m11","m16","m17","m21","m22"]},"explication":"**axe de symétrie**, **parterres géométriques** et **arbres taillés** montrent la nature soumise."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le jardin à la française est une **démonstration de pouvoir** : ce que le roi fait aux arbres, il le fait au royaume."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g1":"d2","g2":"d3"}},"explication":"Moyen Âge : nature **encadrée** ; Renaissance : **observée** ; XVIIe : **soumise** ; XVIIIe : **à rêver**."}]$ex$::jsonb),
  ('720b0dcc-d36b-5605-8a79-d187aef534b0'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le merle et le jardinier","competence":"argumenter","situation":"Une fable inventée à la manière de La Fontaine met en scène un jardinier et un merle. Un tableau rappelle trois grandes manières d’aménager la nature.","documents":[{"id":"fable","type":"texte","genre":"recit","titre":"Le Jardinier et le Merle","blocs":["Un jardinier taillait ses arbres en boules et en pyramides. Un merle, perché sur la haie, le railla : « Tu coupes tout ce qui pousse ! Pourquoi veux-tu que la nature obéisse ? »","Le jardinier répondit : « Parce que je suis le maître. » Le merle s’envola sans un mot, et la première tempête emporta la haie."],"source":"Fable écrite pour l’exercice, à la manière de La Fontaine"},{"id":"jardins","type":"tableau","titre":"Trois jardins","colonnes":["Époque","Le jardin","La nature y est"],"lignes":[["Moyen Âge","Le jardin clos","Encadrée"],["Renaissance","Les jardins italiens","Observée et mise en scène"],["XVIIe siècle","Le jardin à la française","Soumise"]],"enteteLignes":true,"source":"D’après le cours"}],"questions":[{"enonce":"Touche l’animal qui dit la vérité au jardinier.","aide":"Dans une fable, un animal parle pour dire la vérité des hommes.","type":"zone","document":"fable","multiple":true},{"enonce":"Touche les mots du jardinier qui résument l’idée du siècle de Descartes : l’homme comme maître de la nature.","aide":"Cherche ce qu’il répond au merle.","type":"zone","document":"fable","multiple":true},{"enonce":"Le jardinier taille ses arbres en boules et en pyramides. Touche le jardin du tableau qui lui ressemble.","aide":"Arbres taillés, formes géométriques : de quelle époque ?","type":"zone","document":"jardins","multiple":false},{"enonce":"Classe ces éléments selon l’époque.","aide":"Pense à chaque époque : encadrée, observée, soumise.","type":"categories","categories":[{"id":"c0","texte":"Moyen Âge"},{"id":"c1","texte":"Renaissance"},{"id":"c2","texte":"XVIIe siècle"}],"items":[{"id":"i0","texte":"La perspective qui donne de la profondeur"},{"id":"i1","texte":"Un jardin entouré de murs, image du paradis"},{"id":"i2","texte":"Des arbres taillés et des axes de symétrie"},{"id":"i3","texte":"Des grottes et des jeux d’eau"},{"id":"i4","texte":"Des enluminures en aplats sur fond d’or"}]},{"enonce":"Que montre le choix de La Fontaine de faire parler un merle ?","aide":"Dans les Fables, les animaux servent à parler des hommes.","type":"choix","options":[{"id":"a","texte":"La vérité sur les hommes peut venir de la nature"},{"id":"b","texte":"Les oiseaux savent vraiment parler"},{"id":"c","texte":"La nature est toujours soumise à l’homme"},{"id":"d","texte":"Les jardiniers n’écoutent jamais personne"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"Le **merle** dit la vérité au jardinier : La Fontaine se sert des animaux pour dire la vérité des hommes."},{"cle":{"type":"zone","ids":["m33","m34","m35","m36","m37","m38"]},"explication":"**Parce que je suis le maître** résume l’idée de se rendre « comme maître et possesseur de la nature »."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Il ressemble au **jardin à la française**, où la nature est soumise."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c2","i3":"c1","i4":"c0"}},"explication":"Moyen Âge : **enluminures** et **jardin clos** ; Renaissance : **perspective**, **grottes et jeux d’eau** ; XVIIe : **arbres taillés** et **symétrie**."},{"cle":{"type":"choix","ids":["a"]},"explication":"La Fontaine se sert des animaux pour **dire la vérité des hommes**."}]$ex$::jsonb),
  ('a84a4b01-c102-5366-ad58-5feb28ac9c50'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"De La Mecque à Médine, de Médine à Bagdad","competence":"lire-carte","situation":"En 622, Muhammad quitte La Mecque pour une autre ville d’Arabie. Plus tard, les califes gouvernent depuis Damas, puis depuis Bagdad. Suis ces villes sur la carte.","documents":[{"id":"carte","type":"carte","titre":"Quatre villes du monde arabo-musulman","fond":"monde","cadrage":[25,12,58,42],"source":"Carte simplifiée, écrite pour l’exercice.","lieux":[{"id":"z1","lieu":"la-mecque","symbole":"point","nom":"La Mecque"},{"id":"z2","lon":39.61,"lat":24.47,"symbole":"point","nom":"Médine"},{"id":"z3","lieu":"damas","symbole":"point","nom":"Damas"},{"id":"z4","lieu":"bagdad","symbole":"point","nom":"Bagdad"}],"traits":[{"id":"z5","points":["la-mecque",[39.61,24.47]],"style":"fleche","teinte":"corail","etiquette":"Hégire, 622"}]}],"questions":[{"enonce":"Touche la ville où Muhammad arrive en 622, au terme de l’Hégire (suis la flèche).","aide":"La flèche part de La Mecque : touche la ville où elle s’arrête.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche Bagdad, la capitale des califes abbassides.","aide":"Bagdad est au bord du Tigre, bien plus à l’est que Damas.","type":"zone","document":"carte","multiple":false},{"enonce":"Dans quelle direction Muhammad se déplace-t-il quand il va de La Mecque à Médine ?","aide":"Compare la hauteur de La Mecque et celle de Médine sur la carte.","type":"choix","options":[{"id":"a","texte":"Vers l’est"},{"id":"b","texte":"Vers le nord"},{"id":"c","texte":"Vers le sud"},{"id":"d","texte":"Vers l’ouest"}],"multiple":false}]}$ex$::jsonb,
