  ('a84a4b01-c102-5366-ad58-5feb28ac9c50'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les dates et les piliers de l’islam","competence":"se-reperer-temps","situation":"Inès prépare un exposé sur les débuts de l’islam. Elle dispose d’une frise de 600 à 640 et d’un tableau sur les cinq piliers, les gestes de tout croyant.","documents":[{"id":"frise","type":"frise","titre":"La vie de Muhammad","debut":600,"fin":640,"pas":10,"evenements":[{"id":"z1","date":610,"nom":"Prêche"},{"id":"z2","date":622,"nom":"Hégire"},{"id":"z3","date":632,"nom":"Mort"}]},{"id":"piliers","type":"tableau","titre":"Les cinq piliers de l’islam","source":"D’après le cours.","colonnes":["N°","Le pilier","Ce que fait le croyant"],"lignes":[[1,"La profession de foi","Dire qu’il y a un seul Dieu, Allah"],[2,"Les cinq prières","Prier cinq fois par jour"],[3,"?","Donner une part de ses biens aux pauvres"],[4,"Le jeûne du ramadan","Ne pas manger du lever au coucher du soleil pendant un mois"],[5,"?","Se rendre à La Mecque"]]}],"questions":[{"enonce":"Touche sur la frise l’événement qui marque l’an 1 du calendrier musulman.","aide":"Cet événement est le départ de Muhammad de La Mecque vers Médine.","type":"zone","document":"frise","multiple":false},{"enonce":"Pendant combien d’années Muhammad a-t-il prêché avant l’Hégire ?","aide":"Soustrais la date du premier prêche à celle de l’Hégire.","type":"nombre","unite":"ans"},{"enonce":"Combien d’années s’écoulent entre l’Hégire et la mort de Muhammad ?","aide":"Soustrais la date de l’Hégire à celle de sa mort.","type":"nombre","unite":"ans"},{"enonce":"Complète les deux cases « ? » du tableau.","aide":"Lis la colonne de droite : qu’est-ce que le croyant fait aux lignes 3 et 5 ?","type":"trous","segments":["Le pilier n° 3 est l’",0," et le pilier n° 5 est le ",1," à La Mecque."],"banque":["pèlerinage","ramadan","aumône","prière"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"L’**Hégire**, en 622, est l’an 1 du calendrier musulman."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12 ans","explication":"Il prêche depuis 610 et part en 622 : 622 − 610 = **12 ans**."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 ans","explication":"632 − 622 = **10 ans** : en dix ans, il rassemble une communauté qui va bâtir un empire."},{"cle":{"type":"trous","trous":[["aumone"],["pelerinage"]]},"affichage":"aumône · pèlerinage","explication":"Donner aux pauvres, c’est l’**aumône** ; se rendre à La Mecque, c’est le **pèlerinage**."}]$ex$::jsonb),
  ('a84a4b01-c102-5366-ad58-5feb28ac9c50'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une copiste dans la Maison de la Sagesse","competence":"analyser-document","situation":"Yasmin est copiste à Bagdad au IXe siècle. Un schéma montre le chemin du papier ; un récit décrit sa journée.","documents":[{"id":"chemin","type":"chaine","disposition":"ligne","titre":"Le chemin du papier","noeuds":[{"id":"z1","texte":"Chine"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Europe médiévale"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"}]},{"id":"recit","type":"texte","genre":"recit","titre":"Une journée à Bagdad","auteur":"Texte écrit pour l’exercice","blocs":["Bagdad, IXe siècle. Yasmin, jeune copiste, travaille à la Maison de la Sagesse. Elle recopie sur du papier, un produit venu de Chine, la traduction d’un livre grec de médecine.","Son maître lui montre d’autres manuscrits : des textes perses, des textes indiens, un traité d’algèbre d’al-Khwarizmi. « Ici, dit-il, on traduit les savoirs des autres et on les prolonge. »","Le soir, elle croise Jacob, un juif, et Marie, une chrétienne. Ils gardent leur religion, mais paient un impôt spécial que les musulmans ne paient pas. On les appelle les dhimmis."]}],"questions":[{"enonce":"Quel monde joue le rôle de « passeur » à la place du point d’interrogation ?","aide":"Le récit se passe à Bagdad, et le papier y arrive de Chine.","type":"choix","options":[{"id":"a","texte":"L’Empire byzantin"},{"id":"b","texte":"L’empire arabo-musulman"},{"id":"c","texte":"Le royaume des Vikings"},{"id":"d","texte":"L’empire de Charlemagne"}],"multiple":false},{"enonce":"Touche, dans le récit, le produit venu de Chine sur lequel Yasmin écrit.","aide":"Cherche ce qu’elle utilise pour copier le livre.","type":"zone","document":"recit","multiple":false},{"enonce":"Associe chaque savoir à son origine ou à son auteur.","aide":"Quatre savoirs, quatre origines : relis le récit, puis souviens-toi de ton cours.","type":"association","gauche":[{"id":"g0","texte":"Les chiffres"},{"id":"g1","texte":"Le papier"},{"id":"g2","texte":"L’algèbre"},{"id":"g3","texte":"Un canon de médecine"}],"droite":[{"id":"d0","texte":"Écrit par Avicenne"},{"id":"d1","texte":"Fondée par al-Khwarizmi"},{"id":"d2","texte":"Venu de Chine"},{"id":"d3","texte":"Venus d’Inde"}]},{"enonce":"Touche le nom donné aux chrétiens et aux juifs qui vivent dans l’empire.","aide":"Le mot est à la fin du récit, après « On les appelle ».","type":"zone","document":"recit","multiple":false},{"enonce":"Quelle phrase décrit le mieux le statut des dhimmis ?","aide":"Le récit dit qu’ils gardent leur religion, mais qu’ils paient un impôt en plus.","type":"choix","options":[{"id":"a","texte":"Inférieur, mais protégé"},{"id":"b","texte":"Esclaves de l’empire"},{"id":"c","texte":"Persécutés et chassés"},{"id":"d","texte":"Égal à celui des musulmans"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"Le papier passe par l’**empire arabo-musulman**, qui transmet à l’Europe des savoirs et des produits venus de loin."},{"cle":{"type":"zone","ids":["m17"]},"explication":"Yasmin écrit sur du **papier**, venu de Chine, comme les chiffres sont venus d’Inde."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"Chiffres : **Inde** ; papier : **Chine** ; algèbre : **al-Khwarizmi** ; canon de médecine : **Avicenne**. L’empire les transmet à l’Europe."},{"cle":{"type":"zone","ids":["m92"]},"explication":"Ce sont les **dhimmis** : ils gardent leur religion contre un impôt spécial."},{"cle":{"type":"choix","ids":["a"]},"explication":"Leur statut est **inférieur mais protégé** : ce n’est ni l’égalité, ni la persécution."}]$ex$::jsonb),
  ('cb4b906e-b154-5ff3-860a-44f2acb13084'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Mille ans de Rome en Orient","competence":"se-reperer-temps","situation":"Léo prépare une affiche sur l’Empire byzantin. Il place ses dates sur une frise de l’an 300 à l’an 1500.","documents":[{"id":"frise","type":"frise","titre":"L’Empire byzantin en quatre dates","debut":300,"fin":1500,"pas":100,"evenements":[{"id":"z1","date":395,"nom":"Partage de l’Empire"},{"id":"z2","date":1054,"nom":"Schisme"},{"id":"z3","date":1204,"nom":"Pillage"},{"id":"z4","date":1453,"nom":"Chute"}]}],"questions":[{"enonce":"Touche l’événement qui met fin à l’Empire byzantin : la prise de Constantinople par les Ottomans.","aide":"C’est la date la plus récente de la frise.","type":"zone","document":"frise","multiple":false},{"enonce":"Touche l’événement qui sépare l’Église orthodoxe de l’Église catholique.","aide":"Cet événement est daté du XIe siècle.","type":"zone","document":"frise","multiple":false},{"enonce":"Range ces événements du plus ancien au plus récent.","aide":"Lis les dates sous les points de la frise.","type":"ordre","items":[{"id":"a","texte":"Le partage de l’Empire romain"},{"id":"b","texte":"Le pillage de Constantinople par les croisés"},{"id":"c","texte":"Le schisme entre les deux Églises"},{"id":"d","texte":"La chute de Constantinople"}]},{"enonce":"Combien d’années séparent le schisme de 1054 de la chute de Constantinople ?","aide":"Soustrais 1054 à 1453.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"En **1453**, les Ottomans prennent Constantinople : c’est la fin de l’Empire byzantin."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Le **schisme** de **1054** sépare l’Église orthodoxe de l’Église catholique."},{"cle":{"type":"ordre","ids":["a","c","b","d"]},"explication":"**395**, **1054**, **1204**, **1453** : du partage de l’Empire romain à la chute de sa dernière capitale."},{"cle":{"type":"nombre","valeur":399,"tolerance":0},"affichage":"399 ans","explication":"1453 − 1054 = **399 ans**, soit presque quatre siècles."}]$ex$::jsonb),
  ('cb4b906e-b154-5ff3-860a-44f2acb13084'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Anna arrive à Constantinople","competence":"analyser-document","situation":"Anna, marchande de Venise, arrive en bateau à Constantinople. Elle note ce qu’elle voit. Un tableau compare ensuite les deux Églises chrétiennes.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Les notes d’Anna","auteur":"Texte écrit pour l’exercice","blocs":["Anna, marchande de Venise, arrive à Constantinople par la mer. Son navire entre dans le détroit du Bosphore, entre l’Europe et l’Asie. Devant elle se dressent de hautes murailles, triples, que les armées n’ont pas pu forcer.","Sur les quais, des marchands vénitiens, arabes, slaves et scandinaves crient dans leurs langues. L’Église, elle, prie en grec, et les habitants se disent « Romains ».","Au palais, le basileus est à la fois chef de l’armée, chef du gouvernement et chef de l’Église : c’est lui qui nomme le patriarche. On dit que son pouvoir vient de Dieu."]},{"id":"eglises","type":"tableau","titre":"Deux Églises chrétiennes","source":"D’après le cours.","colonnes":["Sujet","Église de Byzance","Église de Rome"],"lignes":[["Langue","Le grec","?"],["Prêtres","Mariage autorisé","Célibat"],["Pape","Son autorité est refusée","Son ? est reconnue"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le nom du détroit sur lequel se trouve Constantinople.","aide":"Le détroit sépare l’Europe de l’Asie.","type":"zone","document":"recit","multiple":false},{"enonce":"Touche le titre que porte l’empereur byzantin.","aide":"Cherche qui est à la fois chef de l’armée, du gouvernement et de l’Église.","type":"zone","document":"recit","multiple":false},{"enonce":"Complète le tableau pour l’Église de Rome.","aide":"À Byzance, c’est le contraire : la langue est le grec et l’autorité du pape est refusée.","type":"trous","segments":["À Rome, on prie en ",0," et on reconnaît l’",1," du pape."],"banque":["refus","latin","autorité","grec"]},{"enonce":"Pourquoi les habitants de l’empire se disent-ils « Romains » ?","aide":"Rappelle-toi ce qui reste de l’Empire romain après 476.","type":"choix","options":[{"id":"a","texte":"Leur empire est l’héritier de l’Empire romain"},{"id":"b","texte":"Ils viennent tous de la ville de Rome"},{"id":"c","texte":"Le pape de Rome est leur chef"},{"id":"d","texte":"Ils parlent latin comme à Rome"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17"]},"explication":"Constantinople est bâtie sur le **Bosphore**, entre l’Europe et l’Asie : une position idéale pour le commerce."},{"cle":{"type":"zone","ids":["m69"]},"explication":"L’empereur est le **basileus** : il nomme même le patriarche, chef de l’Église."},{"cle":{"type":"trous","trous":[["latin"],["autorite"]]},"affichage":"latin · autorité","explication":"Rome emploie le **latin** et reconnaît l’**autorité** du pape ; Byzance emploie le grec et la refuse. C’est ce qui sépare les deux Églises."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’Empire d’Orient est la suite de l’**Empire romain** : eux se disent Romains, et c’est plus tard que des historiens occidentaux les appelleront « byzantins »."}]$ex$::jsonb),
  ('cb4b906e-b154-5ff3-860a-44f2acb13084'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une lettre de Constantinople, avril 1204","competence":"analyser-document","situation":"Un habitant de Constantinople écrit à son cousin pour lui raconter un événement qu’on n’aurait jamais cru possible. Une frise remet la scène dans les mille ans de l’empire.","documents":[{"id":"frise","type":"frise","titre":"Les dates de l’Empire byzantin","debut":300,"fin":1500,"pas":100,"periodes":[{"id":"z1","debut":395,"fin":1453,"nom":"Empire byzantin (395-1453)","teinte":"violet"}],"evenements":[{"id":"z2","date":476,"nom":"Chute de l’Occident"},{"id":"z3","date":1054,"nom":"Schisme"},{"id":"z4","date":1204,"nom":"Pillage"}]},{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un habitant de Constantinople","auteur":"Lettre imaginaire, écrite pour l’exercice","blocs":["Constantinople, avril 1204. Cher cousin, tu ne le croiras pas : la ville est tombée. Depuis des siècles, nos triples murailles arrêtaient tous les assaillants.","Cette fois, ce sont des croisés venus d’Occident qui sont entrés. Ils sont chrétiens comme nous, mais ils parlent latin et obéissent au pape. Ils pillent les églises et emportent nos icônes.","Je prie pour que notre empire se relève de cette épreuve."]}],"questions":[{"enonce":"Combien d’années l’Empire d’Orient survit-il à la chute de l’Empire d’Occident ?","aide":"Relève la date de la chute de l’Occident et la date de la fin de l’empire byzantin dans le titre de la période.","type":"nombre","unite":"ans"},{"enonce":"Touche l’événement de la frise dont parle la lettre.","aide":"La lettre est datée d’avril 1204.","type":"zone","document":"frise","multiple":false},{"enonce":"Touche le mot qui désigne ceux qui ont pris la ville.","aide":"Cherche qui est « venu d’Occident » dans la deuxième phrase du deuxième paragraphe.","type":"zone","document":"lettre","multiple":false},{"enonce":"Pourquoi ce pillage est-il si choquant pour l’auteur de la lettre ?","aide":"Relis ce que l’auteur dit des croisés : « chrétiens comme nous ».","type":"choix","options":[{"id":"a","texte":"L’empereur quitte la ville pour toujours"},{"id":"b","texte":"Les murailles sont détruites par un incendie"},{"id":"c","texte":"Des chrétiens attaquent une grande ville chrétienne"},{"id":"d","texte":"Des armées arabes entrent dans la ville"}],"multiple":false},{"enonce":"Associe chaque date à l’événement qu’elle date.","aide":"Les trois premières dates sont sur la frise ; la dernière termine la période.","type":"association","gauche":[{"id":"g0","texte":"476"},{"id":"g1","texte":"1054"},{"id":"g2","texte":"1204"},{"id":"g3","texte":"1453"}],"droite":[{"id":"d0","texte":"Chute de l’Empire d’Occident"},{"id":"d1","texte":"Pillage de Constantinople par les croisés"},{"id":"d2","texte":"Prise de Constantinople par les Ottomans"},{"id":"d3","texte":"Séparation des Églises orthodoxe et catholique"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":977,"tolerance":0},"affichage":"977 ans","explication":"L’Occident tombe en 476, l’Orient en 1453 : 1453 − 476 = **977 ans**, presque mille ans de plus."},{"cle":{"type":"zone","ids":["z4"]},"explication":"La lettre raconte le **pillage** de 1204, pendant la quatrième croisade."},{"cle":{"type":"zone","ids":["m29"]},"explication":"Ce sont des **croisés**, des chrétiens d’Occident."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les croisés sont **chrétiens**, comme les habitants : la quatrième croisade pille une ville chrétienne."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"**476** : l’Occident tombe ; **1054** : le schisme ; **1204** : le pillage ; **1453** : les Ottomans prennent la ville."}]$ex$::jsonb),
