   $ex${"titre":"Deux envoyés partent en tournée","competence":"analyser-texte","situation":"L’empereur envoie deux hommes de confiance dans les comtés. Un texte, écrit pour l’exercice dans l’esprit d’un capitulaire, leur donne leurs instructions ; un schéma montre ce que deviennent les livres copiés dans les monastères.","documents":[{"id":"ordre","type":"texte","genre":"source","titre":"Instructions à deux envoyés du maître","auteur":"Texte écrit pour l’exercice, dans l’esprit d’un capitulaire","blocs":["L’empereur à ses envoyés, un évêque et un comte du palais : allez deux par deux dans les comtés que je vous confie.","Vous écouterez les plaintes des habitants et vous contrôlerez que les comtes rendent la justice avec équité.","Vous veillerez aussi à ce que chaque monastère ouvre une école. Ensuite vous me ferez un rapport : je le ferai écrire dans un capitulaire et il vaudra loi dans tout l’empire."]},{"id":"chaine","type":"chaine","disposition":"ligne","titre":"Le chemin d’un livre antique","noeuds":[{"id":"z1","texte":"Livre latin antique"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Copie en minuscule caroline"},{"id":"z4","texte":"Livre lu aujourd’hui"}],"liens":[{"de":"z1","a":"z2","texte":"est apporté à"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Touche ceux que les deux envoyés doivent contrôler.","aide":"L’envoyé doit vérifier que la justice est bien rendue : par qui ?","type":"zone","document":"ordre","multiple":false},{"enonce":"Que représente le duo « un évêque et un comte du palais » ?","aide":"Un évêque appartient à l’Église ; un comte n’en fait pas partie.","type":"choix","options":[{"id":"a","texte":"Deux savants venus de la cour d’Alcuin à Aix"},{"id":"b","texte":"Deux comtes qui viennent juger un procès au palais"},{"id":"c","texte":"Un religieux et un laïc, comme les missi dominici"},{"id":"d","texte":"Deux soldats chargés de lever l’armée pour l’empereur"}],"multiple":false},{"enonce":"Touche le mot qui désigne les lois écrites de l’empereur.","aide":"Le mot est dans la dernière phrase du texte.","type":"zone","document":"ordre","multiple":false},{"enonce":"Comment s’appelle l’atelier d’un monastère où des moines recopient les livres ? (un mot, le « ? » du schéma)","aide":"Ce mot latin vient de « scribere », écrire.","type":"texte","placeholder":"un mot latin"},{"enonce":"Pourquoi beaucoup de textes latins de l’Antiquité nous sont-ils parvenus ?","aide":"Regarde le maillon du schéma qui précède « Livre lu aujourd’hui ».","type":"choix","options":[{"id":"a","texte":"Ils étaient gravés dans la pierre"},{"id":"b","texte":"Charlemagne les a tous appris par cœur"},{"id":"c","texte":"Des moines carolingiens les ont recopiés"},{"id":"d","texte":"Ils ont été imprimés au Moyen Âge"}],"multiple":false}]}$ex$::jsonb,
