.","type":"choix","options":[{"id":"a","texte":"Des marchandises continuent d’aller et venir"},{"id":"b","texte":"Seuls les chrétiens ont le droit de commercer"},{"id":"c","texte":"L’Orient n’a rien à vendre à l’Occident"},{"id":"d","texte":"Le commerce est totalement interrompu"}],"multiple":false}]}$ex$::jsonb,
