  ('d08c84fe-8112-5b6b-bb75-0870d4b1c883'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le carnet d’un traducteur de Tolède","competence":"analyser-document","situation":"Vers 1150, à Tolède, trois hommes traduisent un livre d’Aristote. Une carte situe la ville ; le carnet raconte comment le savoir voyage d’une langue à l’autre.","documents":[{"id":"carte","type":"carte","titre":"La Méditerranée au Moyen Âge","fond":"mediterranee","cadrage":[-10,30,40,47],"source":"Carte simplifiée, écrite pour l’exercice.","lieux":[{"id":"z1","lon":-4.02,"lat":39.86,"symbole":"point","nom":"Tolède"},{"id":"z2","lieu":"venise","symbole":"point","nom":"Venise"},{"id":"z3","lieu":"jerusalem","symbole":"point","nom":"Jérusalem"},{"id":"z4","lieu":"constantinople","symbole":"point","nom":"Constantinople"}]},{"id":"carnet","type":"texte","genre":"recit","titre":"Le carnet d’un traducteur","auteur":"Texte écrit pour l’exercice","blocs":["Tolède, vers 1150. Hugo, un clerc chrétien, travaille avec Samuel, un savant juif, et Yusuf, un savant musulman. Devant eux, un livre d’Aristote écrit en grec, déjà traduit en arabe.","Yusuf lit la version arabe à voix haute, Samuel la traduit en langue parlée, et Hugo l’écrit en latin pour les écoles d’Occident.","Dans la pile de livres, un traité de calcul arabe parle de « al-jabr » : l’algèbre. Il présente aussi les chiffres venus d’Inde et le zéro, que les marchands italiens apprennent à utiliser."]}],"questions":[{"enonce":"Touche la ville espagnole où chrétiens, juifs et musulmans traduisent ensemble.","aide":"Cette ville est au centre de l’Espagne.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la ville que le pape Urbain II veut faire reprendre en 1095.","aide":"C’est une ville sainte, à l’est de la Méditerranée.","type":"zone","document":"carte","multiple":false},{"enonce":"Range les étapes du voyage du livre d’Aristote.","aide":"Suis le livre dans le carnet : de quelle langue à quelle langue passe-t-il ?","type":"ordre","items":[{"id":"a","texte":"Redécouvert par l’Occident"},{"id":"b","texte":"Traduit en arabe"},{"id":"c","texte":"Retraduit en latin à Tolède"},{"id":"d","texte":"Écrit en grec"}]},{"enonce":"Touche le mot français qui vient de l’arabe « al-jabr ».","aide":"Cette science calcule avec des lettres et des inconnues.","type":"zone","document":"carnet","multiple":false},{"enonce":"Pourquoi dit-on que la Méditerranée est à la fois une frontière et un pont ?","aide":"Pense aux croisades d’un côté, aux traductions de l’autre.","type":"choix","options":[{"id":"a","texte":"Elle réunit trois civilisations qui ne se battent jamais"},{"id":"b","texte":"Elle sépare des civilisations, mais porte aussi leurs échanges"},{"id":"c","texte":"Elle n’est traversée que par des marchands italiens"},{"id":"d","texte":"Elle sépare les civilisations et ne porte que des armées"}],"multiple":false}]}$ex$::jsonb,
