   $ex${"titre":"La vie d’Aubin, paysan d’une seigneurie","competence":"analyser-document","situation":"Aubin vit dans une seigneurie. Le récit raconte ce qu’il doit au seigneur ; le plan montre où tout se trouve.","documents":[{"id":"plan","type":"schema","titre":"Plan d’une seigneurie","largeur":340,"hauteur":250,"elements":[{"forme":"rect","x":10,"y":10,"l":320,"h":230,"arrondi":14,"teinte":"vert","motif":"clair"},{"forme":"rect","x":25,"y":25,"l":150,"h":95,"teinte":"ambre","motif":"hachures","id":"z1","zone":true},{"forme":"emoji","x":232,"y":62,"emoji":"🏰","taille":40,"id":"z2","zone":true},{"forme":"texte","x":232,"y":94,"texte":"Château","taille":"petit","ancre":"milieu"},{"forme":"emoji","x":305,"y":52,"emoji":"⛪","taille":28,"id":"z3","zone":true},{"forme":"texte","x":305,"y":78,"texte":"Église","taille":"petit","ancre":"milieu"},{"forme":"rect","x":25,"y":150,"l":62,"h":50,"teinte":"jaune","motif":"points","id":"z4","zone":true},{"forme":"rect","x":97,"y":150,"l":62,"h":50,"teinte":"jaune","motif":"points","id":"z5","zone":true},{"forme":"rect","x":169,"y":150,"l":62,"h":50,"teinte":"jaune","motif":"points","id":"z6","zone":true},{"forme":"rect","x":252,"y":150,"l":66,"h":50,"arrondi":6,"teinte":"brun","motif":"clair","texte":"Moulin","id":"z7","zone":true},{"forme":"texte","x":170,"y":224,"texte":"Les champs des paysans, découpés en parcelles","taille":"petit","italique":true,"ancre":"milieu"}]},{"id":"recit","type":"texte","genre":"recit","titre":"La vie d’Aubin","auteur":"Texte écrit pour l’exercice","blocs":["Aubin est un vilain : il est libre, mais pour vivre il cultive une petite parcelle du seigneur, sa tenure, et il verse des redevances.","À la Saint-Rémi, il paie le cens en argent. Après la moisson, il donne au seigneur une part de sa récolte : c’est le champart. Il doit aussi trois jours de corvée sur la réserve, le grand champ que le seigneur exploite pour lui, au pied du château.","Pour moudre son grain, il doit utiliser le moulin du seigneur et payer en échange : c’est une banalité. Enfin, il verse environ un dixième de sa récolte à l’Église : la dîme."]}],"questions":[{"enonce":"Où Aubin fait-il ses journées de corvée ? Touche l’endroit sur le plan.","aide":"Relis le deuxième paragraphe : la réserve est « au pied du château ».","type":"zone","document":"plan","multiple":false},{"enonce":"Touche le bâtiment que les paysans sont obligés d’utiliser en payant.","aide":"Lis le dernier paragraphe : de quoi Aubin a-t-il besoin pour moudre son grain ?","type":"zone","document":"plan","multiple":false},{"enonce":"Touche la redevance qu’Aubin paie en argent.","aide":"Cherche ce que le paysan paie à la Saint-Rémi.","type":"zone","document":"recit","multiple":false},{"enonce":"Associe chaque redevance à ce qu’elle représente.","aide":"Relis le récit paragraphe par paragraphe : chaque redevance y est expliquée.","type":"association","gauche":[{"id":"g0","texte":"Le cens"},{"id":"g1","texte":"Le champart"},{"id":"g2","texte":"La corvée"},{"id":"g3","texte":"La banalité"},{"id":"g4","texte":"La dîme"}],"droite":[{"id":"d0","texte":"Un dixième de la récolte pour l’Église"},{"id":"d1","texte":"Une taxe pour le moulin ou le four"},{"id":"d2","texte":"Une somme d’argent"},{"id":"d3","texte":"Une part de la récolte"},{"id":"d4","texte":"Des journées de travail gratuit"}]},{"enonce":"Aubin est un vilain, pas un serf. Qu’est-ce que cela change pour lui ?","aide":"Le récit commence par dire qu’Aubin est libre.","type":"choix","options":[{"id":"a","texte":"Il n’a aucune redevance à payer au seigneur"},{"id":"b","texte":"Il est attaché à la terre toute sa vie"},{"id":"c","texte":"Il est propriétaire de la réserve"},{"id":"d","texte":"Il est libre de partir, contrairement au serf"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"La corvée se fait sur la **réserve**, le grand champ que le seigneur exploite directement."},{"cle":{"type":"zone","ids":["z7"]},"explication":"Le **moulin** est une banalité : son usage est obligatoire et payant (comme le four et le pressoir)."},{"cle":{"type":"zone","ids":["m30"]},"explication":"Le **cens** est une redevance en argent."},{"cle":{"type":"association","paires":{"g4":"d0","g3":"d1","g0":"d2","g1":"d3","g2":"d4"}},"explication":"**Cens** : argent ; **champart** : part de récolte ; **corvée** : travail gratuit ; **banalité** : taxe d’un équipement du seigneur ; **dîme** : dixième pour l’Église."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le vilain est **libre** : il peut partir, se marier et transmettre son bien ; le serf est attaché à la terre."}]$ex$::jsonb),
