   $ex${"titre":"Avant et après la peste : une seigneurie ébranlée","competence":"lire-graphique","situation":"Entre l’an 1000 et le milieu du XIVe siècle, la population d’une région d’Europe change beaucoup. Un graphique et la chronique d’un curé en racontent l’histoire.","documents":[{"id":"pop","type":"graphique","forme":"barres","titre":"La population d’une région (indice)","source":"Indices écrits pour l’exercice, d’après le cours : elle double de 1000 à 1300, puis un tiers disparaît.","categories":["An 1000","Vers 1300","Après la crise"],"series":[{"nom":"Population","valeurs":[150,300,200],"teinte":"violet"}],"axeY":{"titre":"Population","unite":"indice","min":0,"max":350,"pas":50},"axeX":{"titre":"Époque"}},{"id":"chronique","type":"texte","genre":"recit","titre":"La chronique d’un curé","auteur":"Texte écrit pour l’exercice","blocs":["Année 1349. La peste est passée chez nous. Dans notre village, un habitant sur trois est mort ; des maisons restent vides.","Les champs de plusieurs paysans ne sont plus cultivés : il n’y a plus assez de bras. Le seigneur du château se plaint que ses redevances rentrent mal.","Depuis dix ans, la guerre et les mauvaises récoltes ajoutent à nos malheurs."]}],"questions":[{"enonce":"Par combien la population est-elle multipliée entre l’an 1000 et 1300 ?","aide":"Divise la hauteur de la barre « Vers 1300 » par celle de la barre « An 1000 ».","type":"nombre"},{"enonce":"Quelle part de la population de 1300 disparaît pendant la crise ?","aide":"Calcule la perte entre 300 et 200, puis compare-la à 300.","type":"choix","options":[{"id":"a","texte":"Un tiers"},{"id":"b","texte":"Les trois quarts"},{"id":"c","texte":"La moitié"},{"id":"d","texte":"Un dixième"}],"multiple":false},{"enonce":"Touche le fléau qui frappe le village en 1349.","aide":"C’est une maladie qui a ravagé l’Europe entre 1347 et 1352.","type":"zone","document":"chronique","multiple":false},{"enonce":"Que montre la chronique sur la seigneurie après la peste ?","aide":"Relis ce que dit le curé des champs et des redevances du seigneur.","type":"choix","options":[{"id":"a","texte":"Elle est ébranlée : moins de paysans, donc moins de redevances"},{"id":"b","texte":"Elle disparaît : tous les seigneurs partent en guerre"},{"id":"c","texte":"Elle n’est pas touchée : seuls les villages meurent"},{"id":"d","texte":"Elle est plus riche : les paysans sont moins nombreux"}],"multiple":false},{"enonce":"Range ces étapes de la plus ancienne à la plus récente.","aide":"Pars des progrès agricoles, puis suis leurs conséquences jusqu’à la crise.","type":"ordre","items":[{"id":"a","texte":"Les paysans adoptent de nouveaux outils et défrichent"},{"id":"b","texte":"La population double entre 1000 et 1300"},{"id":"c","texte":"Les récoltes augmentent"},{"id":"d","texte":"La peste noire frappe l’Europe"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"300 ÷ 150 = **2** : la population double grâce aux progrès agricoles."},{"cle":{"type":"choix","ids":["a"]},"explication":"300 − 200 = 100, et 100 est le **tiers** de 300 : famines, peste et guerre emportent un tiers de la population."},{"cle":{"type":"zone","ids":["m3"]},"explication":"La **peste noire** (1347-1352) emporte un grand nombre d’Européens."},{"cle":{"type":"choix","ids":["a"]},"explication":"Moins de paysans, ce sont moins de **redevances** et des champs sans bras : tout le système seigneurial est ébranlé."},{"cle":{"type":"ordre","ids":["a","c","b","d"]},"explication":"Progrès techniques, **récoltes**, **population doublée**, puis la crise : peste noire en 1347-1352."}]$ex$::jsonb),
