  ('f25a8430-454c-5d1f-928a-4dbd248c7a27'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un dimanche à la paroisse, vers 1250","competence":"analyser-document","situation":"Au XIIIe siècle, l’Église est présente à chaque moment de la vie d’un village. Un récit raconte un dimanche ; un tableau liste les sacrements.","documents":[{"id":"dimanche","type":"texte","genre":"recit","titre":"Un dimanche à la paroisse","auteur":"Texte écrit pour l’exercice","blocs":["Dimanche, les cloches sonnent la messe. Tout le village est à l’église : au Moyen Âge, être chrétien n’est pas un choix. Le curé baptise le dernier-né du meunier : c’est l’un des sept sacrements qui jalonnent une vie.","À la sortie, les paysans déposent à la porte de l’église la dîme : environ un dixième de leur récolte. Elle fait vivre le curé et aide les pauvres.","Un frère mendiant prêche sur la place. À l’hôpital voisin, des religieuses soignent des malades. L’Église est aussi propriétaire de champs et de moulins."]},{"id":"sacrements","type":"tableau","titre":"Les sept sacrements","source":"D’après le cours.","colonnes":["N°","Le sacrement"],"lignes":[[1,"Baptême"],[2,"Confirmation"],[3,"?"],[4,"Pénitence"],[5,"Mariage"],[6,"?"],[7,"Extrême-onction"]]}],"questions":[{"enonce":"Touche le mot qui désigne les sept grands moments de la vie religieuse, comme le baptême.","aide":"Le baptême en est un : cherche le mot qui les regroupe.","type":"zone","document":"dimanche","multiple":false},{"enonce":"Un paysan récolte 50 sacs de grain. Combien en donne-t-il à l’Église pour la dîme (environ un dixième) ?","aide":"Divise 50 par 10.","type":"nombre","unite":"sacs"},{"enonce":"Complète les deux cases « ? » du tableau.","aide":"Il manque l’un des sacrements de l’Église, le troisième de la liste officielle.","type":"trous","segments":["Les sacrements manquants sont l’",0," (n° 3) et l’",1," (n° 6)."],"banque":["ordre","eucharistie","aumône","carême"]},{"enonce":"Classe chaque élément : l’Église le reçoit-elle, ou le donne-t-elle ?","aide":"La dîme et les domaines sont des ressources ; le reste est un service rendu.","type":"categories","categories":[{"id":"c0","texte":"Ce que l’Église reçoit"},{"id":"c1","texte":"Ce que l’Église assure"}],"items":[{"id":"i0","texte":"Les revenus de ses domaines"},{"id":"i1","texte":"L’aumône aux pauvres"},{"id":"i2","texte":"La dîme"},{"id":"i3","texte":"L’hôpital"},{"id":"i4","texte":"L’école"},{"id":"i5","texte":"L’accueil des pèlerins"}]},{"enonce":"Que montre ce dimanche sur la place de l’Église ?","aide":"Relis tout ce que l’Église fait dans le récit : messe, dîme, hôpital…","type":"choix","options":[{"id":"a","texte":"Elle ne s’occupe que de la prière du dimanche"},{"id":"b","texte":"Elle est la seule à ne rien posséder"},{"id":"c","texte":"Elle laisse chacun libre de ne pas être chrétien"},{"id":"d","texte":"Elle encadre toute la vie, des sacrements aux soins"}],"multiple":false}]}$ex$::jsonb,
