   $ex${"titre":"Foires, draps et chartes : la ville s’affirme","competence":"lire-carte","situation":"Entre le XIe et le XIIIe siècle, des villes se couvrent de marchands. Une carte situe quatre lieux du commerce ; une charte, écrite pour l’exercice, montre comment une ville gagne sa liberté.","documents":[{"id":"carte","type":"carte","titre":"Quatre lieux du commerce médiéval","fond":"europe","frontieres":true,"cadrage":[-6,41,16,56],"source":"Carte simplifiée, écrite pour l’exercice.","lieux":[{"id":"z1","lieu":"troyes","symbole":"point","nom":"Troyes"},{"id":"z2","lon":3.22,"lat":51.21,"symbole":"point","nom":"Bruges"},{"id":"z3","lieu":"venise","symbole":"point","nom":"Venise"},{"id":"z4","lon":10.69,"lat":53.87,"symbole":"point","nom":"Lübeck"}]},{"id":"charte","type":"texte","genre":"source","titre":"Charte de franchises d’une ville imaginaire","auteur":"Texte écrit pour l’exercice, dans l’esprit des chartes du XIIe siècle","blocs":["Nous, seigneur de cette terre, accordons aux habitants du bourg le droit de s’administrer eux-mêmes.","Chaque année, ils éliront des échevins qui rendront la justice et lèveront les impôts de la ville.","Tout serf qui aura vécu dans la ville un an et un jour sans que son maître le réclame sera libre."]}],"questions":[{"enonce":"Touche la ville des foires de Champagne, où se retrouvent marchands du Nord et du Sud.","aide":"Les foires de Champagne se tiennent à Troyes et à Provins, à l’est de Paris.","type":"zone","document":"carte","multiple":false},{"enonce":"Associe chaque lieu à sa spécialité.","aide":"Bruges est une ville flamande ; Lübeck est au bord de la mer Baltique.","type":"association","gauche":[{"id":"g0","texte":"Bruges"},{"id":"g1","texte":"Venise"},{"id":"g2","texte":"Lübeck"},{"id":"g3","texte":"Troyes"}],"droite":[{"id":"d0","texte":"La Hanse : la mer du Nord et la Baltique"},{"id":"d1","texte":"Le drap"},{"id":"d2","texte":"Les foires, entre Nord et Sud"},{"id":"d3","texte":"Le commerce méditerranéen et la banque"}]},{"enonce":"Touche le mot qui désigne ceux qui administrent la ville.","aide":"Cherche ceux qui rendent la justice et lèvent les impôts.","type":"zone","document":"charte","multiple":false},{"enonce":"Que veut dire « l’air de la ville rend libre » ?","aide":"Relis la dernière phrase de la charte.","type":"choix","options":[{"id":"a","texte":"Les villes ne payent aucun impôt au seigneur"},{"id":"b","texte":"Un serf peut quitter la ville sans payer"},{"id":"c","texte":"Un serf qui y vit un an et un jour devient libre"},{"id":"d","texte":"Tous les habitants deviennent seigneurs"}],"multiple":false}]}$ex$::jsonb,
