  ('00b22604-2e14-50cd-827d-fe2754d38f5e'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Théo, apprenti tisserand","competence":"analyser-document","situation":"Théo veut devenir tisserand de drap dans une grande ville. Les statuts de la corporation et un tableau lui disent comment s’y prendre.","documents":[{"id":"statuts","type":"texte","genre":"source","titre":"Statuts d’une corporation de tisserands","auteur":"Texte écrit pour l’exercice, dans l’esprit des statuts du Moyen Âge","blocs":["Art. 1. Nul ne peut tisser dans la ville s’il n’est reçu dans la corporation.","Art. 2. La qualité de chaque drap sera vérifiée, et un tissu mal fait sera refusé.","Art. 3. Le prix du drap est fixé par les maîtres : nul ne vend moins cher qu’un autre.","Art. 4. Un garçon entre comme apprenti chez un maître. Quand il a fini, il devient compagnon, puis il peut présenter un chef-d’œuvre pour devenir maître."]},{"id":"carriere","type":"tableau","titre":"Les étapes d’un métier","source":"Durées imaginées, écrites pour l’exercice.","colonnes":["Étape","Durée","Statut"],"lignes":[["Apprenti","4 ans","Logé et nourri chez le maître"],["Compagnon","3 ans","Payé à la journée"],["Maître","Sans limite","Patron de son atelier"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui montre que la corporation contrôle la valeur des tissus.","aide":"Cherche ce que la corporation vérifie sur chaque drap.","type":"zone","document":"statuts","multiple":false},{"enonce":"Range les étapes de la carrière d’un artisan.","aide":"Relis l’article 4 des statuts.","type":"ordre","items":[{"id":"a","texte":"Compagnon"},{"id":"b","texte":"Maître"},{"id":"c","texte":"Apprenti"}]},{"enonce":"Théo entre en apprentissage à 13 ans. S’il suit les durées du tableau, à quel âge finit-il sa période de compagnon ?","aide":"Additionne l’âge de départ, la durée d’apprentissage et celle de compagnon.","type":"nombre","unite":"ans"},{"enonce":"Quel est l’effet principal des règles de cette corporation ?","aide":"Relis les articles 1 à 3 : qui peut tisser ? Qui fixe le prix ?","type":"choix","options":[{"id":"a","texte":"Elles ouvrent le métier à tous sans formation"},{"id":"b","texte":"Elles garantissent la qualité mais limitent la concurrence"},{"id":"c","texte":"Elles permettent à chacun de vendre au prix qu’il veut"},{"id":"d","texte":"Elles interdisent aux maîtres de fixer les prix"}],"multiple":false}]}$ex$::jsonb,
