   $ex${"titre":"Lettre d’un bailli à son successeur","competence":"analyser-document","situation":"Un bailli, agent du roi, écrit à celui qui lui succède. Un schéma rappelle comment la guerre de Cent Ans commence.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un bailli du nord du royaume","auteur":"Lettre imaginaire, écrite pour l’exercice","blocs":["Cher successeur, au nord du royaume, c’est le bailli qui représente le roi : il rend la justice, lève l’impôt et fait exécuter les ordres venus de Paris.","Mes collègues du Midi, qu’on appelle sénéchaux, font la même chose. Chaque année, les comptes sont examinés à Paris par la Chambre des comptes, et le Parlement juge les appels.","Le roi s’entoure aussi de juristes, ses légistes, qui défendent son autorité."]},{"id":"guerre","type":"chaine","disposition":"colonne","titre":"Comment commence la guerre de Cent Ans","noeuds":[{"id":"z1","texte":"Les Capétiens directs s’éteignent"},{"id":"z2","texte":"Une nouvelle dynastie monte sur le trône : ?"},{"id":"z3","texte":"Le roi d’Angleterre revendique la couronne"},{"id":"z4","texte":"La guerre dure de 1337 à 1453"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Touche le titre de l’agent du roi qui écrit cette lettre.","aide":"Cherche qui rend la justice et lève l’impôt au nord du royaume.","type":"zone","document":"lettre","multiple":false},{"enonce":"Où l’auteur de la lettre exerce-t-il son métier ?","aide":"Relis la première phrase de la lettre.","type":"choix","options":[{"id":"a","texte":"Dans le nord du royaume"},{"id":"b","texte":"À la cour du roi d’Angleterre"},{"id":"c","texte":"Dans le Midi, comme un sénéchal"},{"id":"d","texte":"Dans un monastère"}],"multiple":false},{"enonce":"Quel est le nom de la dynastie qui remplace les Capétiens directs ? (un nom)","aide":"Elle donne son nom aux rois comme Charles VII.","type":"texte","placeholder":"un nom"},{"enonce":"Combien d’années dure la guerre indiquée dans le dernier cadre du schéma ?","aide":"Soustrais 1337 à 1453.","type":"nombre","unite":"ans"},{"enonce":"Pourquoi dit-on que l’État moderne est en place à la fin de la guerre ?","aide":"Pense à ce que le roi garde après la guerre pour gouverner.","type":"choix","options":[{"id":"a","texte":"Les seigneurs ont retrouvé leur pouvoir complet"},{"id":"b","texte":"Le roi a une armée et un impôt permanents"},{"id":"c","texte":"Il n’y a plus ni Parlement ni baillis"},{"id":"d","texte":"Le roi d’Angleterre est devenu roi de France"}],"multiple":false}]}$ex$::jsonb,
